window.DL_SIGNS=[{"id":"A1","cat":"A","sv":"Varning för farlig kurva","en":"Dangerous bend","svText":"Märket anger en farlig kurva samt kurvans riktning.","enText":"Warns of a dangerous bend and shows which way the bend turns.","tip":"Slow down before the bend, not in it. The sign is used where the bend is sharper than the road suggests.","kw":["curve","corner","turn","kurva"],"img":"A1-1","variants":[{"key":"A1-2","en":"Dangerous bend to the right (A1 shows a bend to the left)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-farlig-kurva/","related":["A2"]},{"id":"A2","cat":"A","sv":"Varning för flera farliga kurvor","en":"Several dangerous bends","svText":"Märket anger flera farliga kurvor samt den första farliga kurvans riktning.","enText":"Warns of several dangerous bends and shows which way the first one turns.","tip":"","kw":["curves","winding road","double bend"],"img":"A2-1","variants":[{"key":"A2-2","en":"Several bends, the first one to the right (A2 shows the first bend to the left)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-flera-farliga-kurvor/","related":["A1"]},{"id":"A3","cat":"A","sv":"Varning för nedförslutning","en":"Steep descent","svText":"Märket anger brant nedförslutning. Siffran anger lutningen i procent och är anpassad till förhållandena på platsen.","enText":"Warns of a steep downhill slope. The number gives the gradient in per cent and is set to match the actual slope at the place.","tip":"A 10 % slope drops 10 metres per 100 metres. Use a lower gear so the engine helps you brake, and keep more distance.","kw":["downhill","gradient","hill","slope","nedförsbacke"],"img":"A3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-nedforslutning/","related":["A4"]},{"id":"A4","cat":"A","sv":"Varning för stigning","en":"Steep ascent","svText":"Märket anger kraftig stigning. Siffran anger stigningen i procent och är anpassad till förhållandena på platsen.","enText":"Warns of a steep uphill slope. The number gives the gradient in per cent and is set to match the actual slope at the place.","tip":"","kw":["uphill","gradient","hill","slope","uppförsbacke"],"img":"A4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-stigning/","related":["A3"]},{"id":"A5","cat":"A","sv":"Varning för avsmalnande väg","en":"Road narrows","svText":"","enText":"Warns that the road or lane gets narrower. The symbol is drawn to match the actual narrowing at the place.","tip":"","kw":["narrowing","narrow road"],"img":"A5-1","variants":[{"key":"A5-2","en":"Road narrows on the right side"},{"key":"A5-3","en":"Road narrows on the left side"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-avsmalnande-vag/","related":[]},{"id":"A6","cat":"A","sv":"Varning för bro","en":"Opening bridge","svText":"Märket anger en öppningsbar bro.","enText":"Warns of a bridge that can be opened (for example to let boats pass).","tip":"","kw":["swing bridge","lifting bridge","drawbridge","bro"],"img":"A6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-bro/","related":[]},{"id":"A7","cat":"A","sv":"Varning för kaj","en":"Quay or river bank","svText":"Märket anger en plats där vägen slutar mot vatten.","enText":"Warns of a place where the road ends at water.","tip":"","kw":["quayside","harbour","water","ferry","kaj"],"img":"A7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-kaj/","related":[]},{"id":"A8","cat":"A","sv":"Varning för ojämn väg","en":"Uneven road","svText":"Märket anger sådana ojämnheter eller skador i vägbanan som medför att det är lämpligt att färdas med lägre hastighet än som annars skulle varit fallet.","enText":"Warns of bumps or damage in the road surface that make it wise to drive more slowly than you otherwise would.","tip":"","kw":["bumpy road","potholes","rough surface"],"img":"A8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-ojamn-vag/","related":["A9"]},{"id":"A9","cat":"A","sv":"Varning för farthinder","en":"Speed bump or dip","svText":"Märkena anger upphöjning eller grop som anlagts som fartdämpande åtgärd.","enText":"Warns of a raised hump or a dip that has been built on purpose to make traffic slow down.","tip":"","kw":["speed hump","traffic calming","farthinder","gupp"],"img":"A9-1","variants":[{"key":"A9-2","en":"Dip (a hollow built to slow traffic). A9 shows a raised speed bump."}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-farthinder/","related":["A8"]},{"id":"A10","cat":"A","sv":"Varning för slirig väg","en":"Slippery road","svText":"Märket anger att vägen kan vara slirig. Endast om det finns särskilda skäl används märket för att varna för halka på grund av snö eller is.","enText":"Warns that the road may be slippery. It is used to warn of slippery snow or ice only if there are special reasons.","tip":"Do not expect this sign every time there is ice. In winter you must judge the grip yourself.","kw":["skid","ice","wet","slippery","halka"],"img":"A10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-slirig-vag/","related":[]},{"id":"A11","cat":"A","sv":"Varning för stenskott","en":"Loose stones","svText":"Märket anger risk för stenskott. Märket används inte på grusvägar eller liknande vägar där stenskott är vanligt förekommande.","enText":"Warns of the risk of stones being thrown up by tyres. It is not used on gravel roads and similar roads, where this is common.","tip":"Keep a longer distance to the vehicle in front so you are not hit by stones it throws up.","kw":["loose chippings","gravel","stone chips","stenskott"],"img":"A11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-stenskott/","related":[]},{"id":"A12","cat":"A","sv":"Varning för stenras","en":"Falling rocks","svText":"Märket anger risk för stenras och för att stenar kan förekomma på vägen på grund av stenras. Symbolen är anpassad efter förhållandena på platsen.","enText":"Warns of the risk of rock falls, and that stones from a rock fall may lie on the road. The symbol is drawn to match the place.","tip":"","kw":["rockfall","landslide","stenras"],"img":"A12-1","variants":[{"key":"A12-2","en":"Falling rocks, with the rock face on the left side (A12 shows it on the right)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-stenras/","related":[]},{"id":"A13","cat":"A","sv":"Varning för övergångsställe","en":"Pedestrian crossing ahead","svText":"","enText":"Warns of a pedestrian crossing ahead.","tip":"This yellow triangle is only a warning. The crossing itself is marked with sign B3 and white stripes on the road.","kw":["zebra crossing","crosswalk","övergångsställe"],"img":"A13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-overgangsstalle/","related":["B3","A14"]},{"id":"A14","cat":"A","sv":"Varning för gående","en":"Pedestrians","svText":"Märket anger en vägsträcka där gående ofta korsar eller uppehåller sig på eller vid vägen.","enText":"Warns of a stretch of road where pedestrians often cross or walk on or beside the road.","tip":"","kw":["people walking","walkers","gående"],"img":"A14","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-gaende/","related":["A13","A15"]},{"id":"A15","cat":"A","sv":"Varning för barn","en":"Children","svText":"Märket anger en vägsträcka där barn ofta korsar eller uppehåller sig på eller vid vägen.","enText":"Warns of a stretch of road where children often cross or spend time on or beside the road.","tip":"Often placed near schools and playgrounds. Children can run out without looking, so lower your speed and be ready to stop.","kw":["school","kids","playground","barn"],"img":"A15-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-barn/","related":["A14"]},{"id":"A16","cat":"A","sv":"Varning för cyklande och mopedförare","en":"Cyclists and moped riders","svText":"Märket anger en vägsträcka där cyklande eller mopedförare ofta korsar eller kör in på vägen.","enText":"Warns of a stretch of road where cyclists or moped riders often cross the road or ride out onto it.","tip":"","kw":["bicycles","bikes","cycle crossing","cyklister"],"img":"A16-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-cyklande-och-mopedforare/","related":[]},{"id":"A17","cat":"A","sv":"Varning för skidåkare","en":"Skiers","svText":"Märket anger en plats där skidåkare ofta korsar eller uppehåller sig på vägen.","enText":"Warns of a place where skiers often cross or spend time on the road.","tip":"","kw":["ski track","skiing","skidåkare"],"img":"A17-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-skidakare/","related":[]},{"id":"A18","cat":"A","sv":"Varning för ridande","en":"Horse riders","svText":"Märket anger en vägsträcka där ridande ofta korsar eller uppehåller sig på vägen.","enText":"Warns of a stretch of road where people on horseback often cross or spend time on the road.","tip":"Pass horses slowly and with plenty of space. Horses can be frightened by noise and sudden movement.","kw":["horses","riding","ridande"],"img":"A18-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-ridande/","related":[]},{"id":"A19","cat":"A","sv":"Varning för djur","en":"Animals","svText":"Märket anger en plats eller vägsträcka där det finns särskild risk för djur på eller vid vägen. Andra symboler kan förekomma på märket. Transportstyrelsen får meddela föreskrifter om vilka andra symboler som får förekomma.","enText":"Warns of a place or stretch of road where there is a special risk of animals on or beside the road. The basic sign shows an elk (moose); other symbols show other animals.","tip":"The elk (moose) sign is the best known. Elk are most active at dawn and dusk. If you see one animal, expect more.","kw":["elk","moose","deer","wildlife","älg","vilt","viltolycka"],"img":"A19-1","variants":[{"key":"A19-2","en":"Deer (Swedish: hjortdjur)"},{"key":"A19-3","en":"Cattle (Swedish: ko)"},{"key":"A19-4","en":"Horses (Swedish: häst)"},{"key":"A19-5","en":"Reindeer (Swedish: ren)"},{"key":"A19-6","en":"Sheep (Swedish: får)"},{"key":"A19-7","en":"Wild boar (Swedish: vildsvin)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-djur/","related":[]},{"id":"A20","cat":"A","sv":"Varning för vägarbete","en":"Road works","svText":"Märket anger en vägsträcka där vägarbete eller liknande arbete pågår.","enText":"Warns of a stretch of road where road works or similar work is going on.","tip":"Workers may be very close to traffic. Follow the temporary signs and markings (often yellow) and slow down.","kw":["roadworks","construction","vägarbete"],"img":"A20-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-vagarbete/","related":["A21"]},{"id":"A21","cat":"A","sv":"Slut på sträcka med vägarbete","en":"End of road works","svText":"Märket anger slut på en vägsträcka med vägarbete som märkts ut med märke A20, varning för vägarbete. Märket är inte uppsatt om det ändå tydligt framgår var sträckan slutar.","enText":"Marks the end of a stretch of road works that was marked with sign A20. It is left out if it is clear anyway where the stretch ends.","tip":"","kw":["roadworks end"],"img":"A21-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/slut-pa-stracka-med-vagarbete/","related":["A20"]},{"id":"A22","cat":"A","sv":"Varning för flerfärgssignal","en":"Traffic signals ahead","svText":"Märket anger en plats där trafiken regleras med flerfärgssignal med tre ljusöppningar. Inom tättbebyggt område är märket uppsatt endast om det finns särskilda skäl för det.","enText":"Warns of a place where traffic is controlled by traffic lights with three lamps (red, yellow, green). Inside built-up areas it is only put up if there are special reasons.","tip":"","kw":["traffic lights","stop lights","trafikljus"],"img":"A22-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-flerfargssignal/","related":[]},{"id":"A23","cat":"A","sv":"Varning för lågt flygande flygplan","en":"Low-flying aircraft","svText":"","enText":"Warns of low-flying aircraft, for example near the end of a runway.","tip":"","kw":["airport","planes","airfield"],"img":"A23-1","variants":[{"key":"A23-2","en":"The same warning with the aircraft drawn in the other direction"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-lagt-flygande-flygplan/","related":[]},{"id":"A24","cat":"A","sv":"Varning för sidvind","en":"Side wind","svText":"Märket anger en vägsträcka där det ofta förekommer stark sidvind. Symbolen är anpassad efter förhållandena på platsen.","enText":"Warns of a stretch of road where strong side winds are common. The symbol is drawn to match the place.","tip":"Strong gusts can push a car, a trailer or a motorcycle sideways, for example on bridges and in openings in a forest.","kw":["crosswind","wind","gusts"],"img":"A24-1","variants":[{"key":"A24-2","en":"Side wind from the other side (the windsock points away from where the wind comes from)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-sidvind/","related":[]},{"id":"A25","cat":"A","sv":"Varning för mötande trafik","en":"Two-way traffic","svText":"Märket anger att en körbana med enkelriktad trafik övergår i en körbana med trafik i båda riktningarna.","enText":"Warns that a carriageway with one-way traffic becomes a carriageway with traffic in both directions.","tip":"","kw":["oncoming traffic","two way","mötande trafik"],"img":"A25-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-motande-trafik/","related":[]},{"id":"A26","cat":"A","sv":"Varning för tunnel","en":"Tunnel","svText":"","enText":"Warns of a tunnel ahead.","tip":"","kw":["tunnel"],"img":"A26-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-tunnel/","related":["E26"]},{"id":"A27","cat":"A","sv":"Varning för svag vägkant eller hög körbanekant","en":"Soft verge or high road edge","svText":"","enText":"Warns of a weak road edge, or of a high step down from the edge of the carriageway.","tip":"","kw":["soft shoulder","verge","edge drop"],"img":"A27-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-svag-vagkant-eller-hog-korbanekant/","related":[]},{"id":"A28","cat":"A","sv":"Varning för vägkorsning","en":"Crossroads (right-hand rule)","svText":"Märket anger en vägkorsning där bestämmelserna i 3 kap. 18 § trafikförordningen (1998:1276) är tillämpliga.","enText":"Warns of a junction where the right-hand rule applies, that is, you must give way to vehicles coming from your right (Road Traffic Ordinance, chapter 3, section 18).","tip":"The X means nobody has priority by signs. Every driver gives way to traffic from the right.","kw":["junction","intersection","högerregeln","right hand rule"],"img":"A28-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-vagkorsning/","related":["A29"]},{"id":"A29","cat":"A","sv":"Varning för vägkorsning där trafikanter på anslutande väg har väjningsplikt eller stopplikt","en":"Junction where side roads must give way","svText":"Märket anger en vägkorsning där förare av fordon på anslutande vägar har väjningsplikt eller stopplikt. Symbolen är anpassad efter förhållandena på platsen.","enText":"Warns of a junction where drivers on the side roads have to give way or stop. You are on the road with priority. The symbol shows the shape of the junction; the wide line is your road.","tip":"You have priority here, but still look out. Someone on the side road may not stop.","kw":["junction","side road","priority road","intersection"],"img":"A29-1","variants":[{"key":"A29-2","en":"The junction drawn with a different layout"},{"key":"A29-3","en":"The junction drawn with a different layout"},{"key":"A29-4","en":"The junction drawn with a different layout"},{"key":"A29-5","en":"The junction drawn with a different layout"},{"key":"A29-6","en":"The junction drawn with a different layout"},{"key":"A29-7","en":"The junction drawn with a different layout"},{"key":"A29-8","en":"The junction drawn with a different layout"},{"key":"A29-9","en":"The junction drawn with a different layout"},{"key":"A29-10","en":"The junction drawn with a different layout"},{"key":"A29-11","en":"The junction drawn with a different layout"},{"key":"A29-12","en":"The junction drawn with a different layout"},{"key":"A29-13","en":"The junction drawn with a different layout"},{"key":"A29-14","en":"The junction drawn with a different layout"},{"key":"A29-15","en":"The junction drawn with a different layout"},{"key":"A29-16","en":"The junction drawn with a different layout"},{"key":"A29-17","en":"The junction drawn with a different layout"},{"key":"A29-18","en":"The junction drawn with a different layout"},{"key":"A29-19","en":"The junction drawn with a different layout"},{"key":"A29-20","en":"The junction drawn with a different layout"},{"key":"A29-21","en":"The junction drawn with a different layout"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-vagkorsning-dar-trafikanter-pa-anslutande-vag-har-vajningsplikt-eller-stopplikt/","related":["A28","B4"]},{"id":"A30","cat":"A","sv":"Varning för cirkulationsplats","en":"Roundabout ahead","svText":"","enText":"Warns of a roundabout ahead.","tip":"When you enter a roundabout you must give way to all vehicles already in it.","kw":["roundabout","rondell","cirkulationsplats"],"img":"A30-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-cirkulationsplats/","related":["D3"]},{"id":"A31","cat":"A","sv":"Varning för långsamtgående fordon","en":"Slow-moving vehicles","svText":"Märket anger en plats där långsamtgående fordon ofta korsar eller kör in på vägen.","enText":"Warns of a place where slow vehicles often cross the road or drive out onto it, for example tractors.","tip":"","kw":["tractor","farm vehicles"],"img":"A31","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-langsamtgaende-fordon/","related":[]},{"id":"A32","cat":"A","sv":"Varning för fordon med förspänt dragdjur","en":"Horse-drawn vehicles","svText":"Märket anger en vägsträcka där fordon förspända med dragdjur ofta korsar eller uppehåller sig på vägen. Andra symboler kan förekomma på märket. Transportstyrelsen får meddela föreskrifter om vilka andra symboler som får förekomma.","enText":"Warns of a stretch of road where vehicles pulled by animals often cross or travel on the road. Other symbols can be used.","tip":"","kw":["horse and cart","carriage","dragdjur"],"img":"A32-1","variants":[{"key":"A32-2","en":"Dog sled"},{"key":"A32-3","en":"Trotting horse with a sulky"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-fordon-med-forspant-dragdjur/","related":[]},{"id":"A33","cat":"A","sv":"Varning för terrängskotertrafik","en":"Snowmobiles","svText":"Märket anger en plats där terrängskotrar ofta korsar eller kör in på vägen.","enText":"Warns of a place where snowmobiles and other off-road scooters often cross the road or drive out onto it.","tip":"","kw":["snowmobile","skoter","terrängskoter"],"img":"A33-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-terrangskotertrafik/","related":[]},{"id":"A34","cat":"A","sv":"Varning för kö","en":"Queues likely","svText":"Märket anger en vägsträcka där det finns risk för köbildning.","enText":"Warns of a stretch of road where there is a risk of queues building up.","tip":"","kw":["traffic jam","queue","congestion","kö"],"img":"A34-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-ko/","related":[]},{"id":"A35","cat":"A","sv":"Varning för järnvägskorsning med bommar","en":"Level crossing with barriers","svText":"Märket anger en korsning med järnväg eller spårväg där det finns bommar.","enText":"Warns of a crossing with a railway or tramway where there are barriers.","tip":"","kw":["railway crossing","train","gates","bommar"],"img":"A35-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-jarnvagskorsning-med-bommar/","related":["A36","A37","A39"]},{"id":"A36","cat":"A","sv":"Varning för järnvägskorsning utan bommar","en":"Level crossing without barriers","svText":"","enText":"Warns of a railway crossing that has no barriers.","tip":"No barriers means you must look and listen for trains yourself.","kw":["railway crossing","train","unguarded crossing"],"img":"A36-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-jarnvagskorsning-utan-bommar/","related":["A35","A37","A39"]},{"id":"A37","cat":"A","sv":"Varning för korsning med spårväg utan bommar","en":"Tramway crossing without barriers","svText":"","enText":"Warns of a crossing with a tramway that has no barriers.","tip":"","kw":["tram","streetcar","spårväg"],"img":"A37-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-korsning-med-sparvag-utan-bommar/","related":["A35","A36"]},{"id":"A38","cat":"A","sv":"Avstånd till plankorsning","en":"Distance to level crossing","svText":"Märkena anger avståndet till en plankorsning i tredjedelar. Märket med tre markeringar är utom tättbebyggt område, uppsatt under något av märkena A35, varning för järnvägskorsning med bommar, A36, varning för järnvägskorsning utan bommar, eller A37, varning för korsning med spårväg utan bommar. Märket med två markeringar anger två tredjedels avstånd till plankorsning och märket med en markering anger den sista tredjedelen av avståndet.","enText":"Count-down markers that show the distance to a level crossing in thirds. Outside built-up areas the marker with three stripes is placed under sign A35, A36 or A37. The marker with two stripes means two thirds of the distance is left, and the one with one stripe marks the last third.","tip":"","kw":["countdown markers","railway","level crossing"],"img":"A38-1","variants":[{"key":"A38-2","en":"Two stripes – two thirds of the distance left"},{"key":"A38-3","en":"One stripe – the last third"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/avstand-till-plankorsning/","related":["A35","A36"]},{"id":"A39","cat":"A","sv":"Kryssmärke","en":"St Andrew's cross (level crossing)","svText":"Märket anger en korsning med järnväg eller spårväg med ett eller flera spår. Märket är uppsatt omedelbart före en plankorsning. Det behöver inte vara uppsatt vid enskild väg med lite trafik där det kan underlåtas utan fara för trafiksäkerheten. Märket kan även vara uppsatt viden annan korsning med järnväg eller spårväg än en plankorsning.","enText":"Marks a crossing with a railway or tramway with one or more tracks. It is placed immediately before a level crossing. It may be left out on a private road with little traffic, where that can be done without danger. It can also be used at other crossings with a railway or tramway.","tip":"A double cross means there is more than one track. When one train has passed, another may be coming.","kw":["railway crossing","cross buck","kryssmärke","level crossing"],"img":"A39-1","variants":[{"key":"A39-2","en":"One track – narrow, upright version"},{"key":"A39-3","en":"More than one track (double cross)"},{"key":"A39-4","en":"More than one track – narrow, upright version"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/kryssmarke/","related":["A35","A36"]},{"id":"A40","cat":"A","sv":"Varning för annan fara","en":"Other danger","svText":"Märket anger en annan fara än sådan som kan anges med något annat varningsmärke. Farans art anges på en tilläggstavla.","enText":"Warns of a danger that no other warning sign covers. An additional panel below it says what the danger is.","tip":"","kw":["danger","exclamation mark","caution"],"img":"A40-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-annan-fara/","related":[]},{"id":"A41","cat":"A","sv":"Varning för olycka","en":"Accident","svText":"","enText":"Warns that there has been a traffic accident on the road ahead.","tip":"Slow down, be ready to stop and follow instructions from the police or rescue services.","kw":["crash","accident","olycka"],"img":"A41","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/varningsmarken/varning-for-olycka/","related":[]},{"id":"B1","cat":"B","sv":"Väjningsplikt","en":"Give way","svText":"Märket anger att förare har väjningsplikt mot fordon på korsande väg eller led och att bestämmelserna i 3 kap. 5 § trafikförordningen (1998:1276) är tillämpliga. Märket kan vara uppsatt tillsammans med tilläggstavla T2, avstånd, som förberedande upplysning om väjningsplikt och tillsammans med tilläggstavla T3, avstånd till stopplikt, som förberedande upplysning om stopplikt. Om samtliga tillfarter i en korsning har väjningsplikt anges detta med tilläggstavla T13, flervägsväjning .","enText":"You must give way to vehicles on the road or route you are about to cross or enter. Chapter 3, section 5 of the Road Traffic Ordinance applies – show clearly in good time that you will give way by slowing down or stopping, and go on only when it causes no danger or obstruction. With additional panel T2 (distance) it warns in advance of a give-way point; with T3 it warns in advance of a stop sign. Panel T13 means that all roads into the junction have to give way.","tip":"Give way does not always mean stop. If you can see that the road is clear, you may drive on without stopping.","kw":["yield","väjningsplikt","triangle","give way"],"img":"B1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/vajningsplikt/","related":["B2","A29"]},{"id":"B2","cat":"B","sv":"Stopplikt","en":"Stop","svText":"Märket anger att förare har stopplikt före infart på korsande väg, led eller spårområde och att bestämmelserna i 3 kap. 19 § trafikförordningen är tillämpliga. Om samtliga tillfarter i en korsning har stopplikt anges detta med tilläggstavla T14, flervägsstopp.","enText":"You must stop before you drive into the crossing road, route or track area. Chapter 3, section 19 of the Road Traffic Ordinance applies – stop at the stop line, or if there is none, immediately before you enter the crossing road. Panel T14 means that all roads into the junction must stop.","tip":"You must always come to a complete stop, even if you can see that the road is empty. After stopping you still have to give way.","kw":["stop sign","stopplikt","octagon"],"img":"B2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/stopplikt/","related":["B1"]},{"id":"B3","cat":"B","sv":"Övergångsställe","en":"Pedestrian crossing","svText":"Märkena, som är likvärdiga och kan användas var för sig eller tillsammans, anger ett övergångsställe. Vid obevakade övergångsställen är för fordonsförare bestämmelserna i 3 kap. 61 § och för gående bestämmelserna i 7 kap. 4 § trafikförordningen tillämpliga.","enText":"Marks a pedestrian crossing. The two versions mean exactly the same and can be used alone or together. At an unguarded crossing (one without traffic lights or police), drivers must give way to pedestrians who are on the crossing or about to step onto it, and pedestrians must take account of the distance and speed of approaching vehicles.","tip":"","kw":["zebra crossing","crosswalk","övergångsställe"],"img":"B3-1","variants":[{"key":"B3-2","en":"The same sign with a different figure – both versions mean the same"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/overgangsstalle/","related":["A13","B8"]},{"id":"B4","cat":"B","sv":"Huvudled","en":"Main road","svText":"Märket är uppsatt vid huvudledens början och upprepat efter varje korsning med annan väg än sådan som avses i 3 kap. 21 § andra stycket trafikförordningen, om det inte ändå tydligt framgår att huvudleden fortsätter efter korsningen.","enText":"Marks the start of a main road (priority road). Traffic coming onto it from side roads must give way. The sign is repeated after each junction, unless it is clear anyway that the main road continues. Exits from places such as car parks, petrol stations and private property do not count as junctions here.","tip":"On a main road you may not park (you may stop briefly). The right-hand rule does not apply to traffic from side roads.","kw":["priority road","huvudled","yellow diamond"],"img":"B4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/huvudled/","related":["B5","A29"]},{"id":"B5","cat":"B","sv":"Huvudled upphör","en":"End of main road","svText":"","enText":"Marks the end of a main road (priority road). After this sign you no longer have priority over side roads because of the main road.","tip":"","kw":["end of priority road","huvudled upphör"],"img":"B5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/huvudled-upphor/","related":["B4"]},{"id":"B6","cat":"B","sv":"Väjningsplikt mot mötande trafik","en":"Give way to oncoming traffic","svText":"","enText":"You may not drive into the stretch ahead (often a narrow section) if doing so would hinder vehicles coming towards you. Let them pass first.","tip":"","kw":["narrow road","priority to oncoming traffic","single lane"],"img":"B6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/vajningsplikt-mot-motande-trafik/","related":["B7"]},{"id":"B7","cat":"B","sv":"Mötande trafik har väjningsplikt","en":"Oncoming traffic must give way","svText":"","enText":"You have priority over oncoming traffic on the narrow stretch ahead. Drivers coming towards you must give way.","tip":"Priority is not a right to force your way through. If the other driver does not give way, you must still avoid a collision.","kw":["narrow road","priority over oncoming traffic"],"img":"B7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/motande-trafik-har-vajningsplikt/","related":["B6"]},{"id":"B8","cat":"B","sv":"Cykelöverfart","en":"Cycle crossing","svText":"Märket anger en cykelöverfart. Vid cykelöverfarter är för fordonsförare bestämmelserna i 3 kap. 61 a § och för cyklande och förare av moped klass II bestämmelserna i 6 kap. 6 § trafikförordningen tillämpliga.","enText":"Marks a cycle crossing (cykelöverfart). Drivers must give way to cyclists and riders of class II mopeds who are on the crossing or about to ride onto it. Cyclists must take account of the distance and speed of approaching vehicles.","tip":"Do not mix it up with a cycle passage (cykelpassage), which is only road markings without this sign. At a passage you adapt your speed, but at a crossing with this sign you must give way.","kw":["cycle crossing","bike crossing","cykelöverfart"],"img":"B8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vajningspliktsmarken/cykeloverfart/","related":["B3","A16"]},{"id":"C1","cat":"C","sv":"Förbud mot infart med fordon","en":"No entry","svText":"","enText":"Driving any vehicle into the road from this direction is prohibited. It is used, for example, at the far end of a one-way street.","tip":"A prohibition aimed at vehicles does not apply to a person who walks beside a bicycle or moped, unless a panel says so.","kw":["no entry","one way","wrong way","infart förbjuden"],"img":"C1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-infart-med-fordon/","related":["C2","E16"]},{"id":"C2","cat":"C","sv":"Förbud mot trafik med fordon","en":"No vehicles","svText":"","enText":"Traffic with all vehicles is prohibited, in both directions.","tip":"","kw":["closed to vehicles","road closed","no traffic"],"img":"C2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-fordon/","related":["C1"]},{"id":"C3","cat":"C","sv":"Förbud mot trafik med annat motordrivet fordon än moped klass II","en":"No motor vehicles (except class II mopeds)","svText":"Avser förbudet även moped klass II anges detta på en tilläggstavla.","enText":"Traffic with motor vehicles other than class II mopeds is prohibited. If class II mopeds are also prohibited, a panel says so.","tip":"","kw":["no cars","no motorcycles","motor vehicles prohibited"],"img":"C3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-annat-motordrivet-fordon-an-moped-klass-ii/","related":["C4","C5"]},{"id":"C4","cat":"C","sv":"Förbud mot trafik med motordrivet fordon med fler än två hjul","en":"No motor vehicles with more than two wheels","svText":"","enText":"Traffic with motor vehicles that have more than two wheels is prohibited – for example cars. Two-wheeled motorcycles and mopeds may still use the road.","tip":"","kw":["no cars"],"img":"C4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-motordrivet-fordon-med-fler-an-tva-hjul/","related":["C3","C5"]},{"id":"C5","cat":"C","sv":"Förbud mot trafik med motorcykel och moped klass I","en":"No motorcycles or class I mopeds","svText":"","enText":"Traffic with motorcycles and class I mopeds is prohibited.","tip":"","kw":["no motorcycles","no mopeds","no MC"],"img":"C5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-motorcykel-och-moped-klass-i/","related":["C3","C4","C11"]},{"id":"C6","cat":"C","sv":"Förbud mot trafik med motordrivet fordon med tillkopplad släpvagn","en":"No motor vehicles with a trailer","svText":"Märket anger förbud mot trafik med motordrivet fordon med tillkopplad släpvagn av annat slag än påhängsvagn eller släpkärra. Avser förbudet även trafik med motordrivet fordon med tillkopplad påhängsvagn eller släpkärra anges det på en tilläggstavla. Avser förbudet endast fordonståg med släpvagn vars totalvikt överstiger visst tontal anges det på tilläggstavla T5, totalvikt.","enText":"Traffic with motor vehicles towing a trailer is prohibited. The ban does not cover semi-trailers or light single-axle trailers of the kind called släpkärra unless a panel says so. If the ban only covers combinations whose trailer weighs more than a certain total weight, panel T5 shows that weight.","tip":"A släpkärra is a trailer with a fixed drawbar that puts only a small part of its weight on the towing vehicle – most ordinary car trailers are of this kind.","kw":["no trailers","trailer ban"],"img":"C6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-motordrivet-fordon-med-tillkopplad-slapvagn/","related":[]},{"id":"C7","cat":"C","sv":"Förbud mot trafik med tung lastbil","en":"No heavy trucks","svText":"","enText":"Traffic with heavy trucks (total weight over 3,500 kg) is prohibited. If the ban also covers light trucks, a panel says so.","tip":"","kw":["no lorries","no HGV","lastbil"],"img":"C7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-tung-lastbil/","related":["C29"]},{"id":"C8","cat":"C","sv":"Förbud mot trafik med traktor och motorredskap klass II","en":"No tractors or class II motor implements","svText":"Avser förbudet även trafik med traktor b eller motorredskap klass I anges det på en tilläggstavla.","enText":"Traffic with tractors (class a) and class II motor implements (machines built for at most 30 km/h) is prohibited. If the ban also covers class b tractors or class I motor implements, a panel says so.","tip":"","kw":["no tractors","traktor"],"img":"C8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-traktor-och-motorredskap-klass-ii/","related":[]},{"id":"C9","cat":"C","sv":"Förbud mot trafik med fordon lastat med farligt gods","en":"No vehicles carrying dangerous goods","svText":"Märket anger förbud mot trafik med fordon med sådan last som omfattas av krav på märkning med orangefärgad skylt enligt föreskrifter som har meddelats med stöd av lagen (2006:263) om transport av farligt gods. Tillsammans med tilläggstavla T23, tunnelkategori, anger märket tunnelkategori.","enText":"Traffic with vehicles carrying a load that must be marked with orange plates under the rules on transport of dangerous goods is prohibited. With panel T23 the sign shows the category of a road tunnel.","tip":"","kw":["hazardous goods","ADR","dangerous goods","farligt gods"],"img":"C9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-fordon-lastat-med-farligt-gods/","related":["D12"]},{"id":"C10","cat":"C","sv":"Förbud mot trafik med cykel och moped klass II","en":"No cycles or class II mopeds","svText":"Avser förbudet även trafik med moped klass I anges det på en tilläggstavla.","enText":"Traffic with bicycles and class II mopeds is prohibited. If class I mopeds are also banned, a panel says so.","tip":"","kw":["no bikes","no bicycles","no cycling"],"img":"C10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-cykel-och-moped-klass-ii/","related":["C11"]},{"id":"C11","cat":"C","sv":"Förbud mot trafik med moped klass II","en":"No class II mopeds","svText":"Avser förbudet även trafik med moped klass I anges det på en tilläggstavla.","enText":"Traffic with class II mopeds is prohibited. If class I mopeds are also banned, a panel says so.","tip":"","kw":["no mopeds"],"img":"C11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-moped-klass-ii/","related":["C10","C5"]},{"id":"C12","cat":"C","sv":"Förbud mot trafik med fordon förspänt med dragdjur","en":"No horse-drawn vehicles","svText":"","enText":"Traffic with vehicles pulled by animals is prohibited.","tip":"","kw":["no carts","no horses"],"img":"C12-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-fordon-forspant-med-dragdjur/","related":[]},{"id":"C13","cat":"C","sv":"Förbud mot trafik med terrängmotorfordon och terrängsläp","en":"No off-road vehicles","svText":"Gäller förbudet inte terrängvagn anges det på en tilläggstavla.","enText":"Traffic with off-road motor vehicles (such as snowmobiles) and off-road trailers is prohibited. If the ban does not cover terrain vehicles over 450 kg (terrängvagn), a panel says so.","tip":"","kw":["no snowmobiles","terräng","skoter"],"img":"C13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-terrangmotorfordon-och-terrangslap/","related":[]},{"id":"C14","cat":"C","sv":"Förbud mot ridning","en":"No horse riding","svText":"Avser förbudet även ledande av riddjur anges det på en tilläggstavla.","enText":"Riding is prohibited. If leading a horse is also prohibited, a panel says so.","tip":"","kw":["no horses","no riding"],"img":"C14-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-ridning/","related":[]},{"id":"C15","cat":"C","sv":"Förbud mot gångtrafik","en":"No pedestrians","svText":"","enText":"Pedestrian traffic is prohibited.","tip":"","kw":["no walking","no pedestrians"],"img":"C15-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-gangtrafik/","related":[]},{"id":"C16","cat":"C","sv":"Begränsad fordonsbredd","en":"Width limit","svText":"Märket anger förbud mot trafik med fordon över en viss bredd. Största tillåtna bredd anges på märket.","enText":"Vehicles wider than the width shown on the sign are prohibited.","tip":"","kw":["maximum width","narrow","bredd"],"img":"C16-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransad-fordonsbredd/","related":[]},{"id":"C17","cat":"C","sv":"Begränsad fordonshöjd","en":"Height limit","svText":"Märket anger förbud mot trafik med fordon över en viss höjd om den fria höjden är lägre än 4,5 meter. Högsta tillåtna fordonshöjd anges på märket.","enText":"Vehicles higher than the height shown on the sign are prohibited. It is used where the free height is less than 4.5 metres.","tip":"The height includes any load, a roof box or bicycles on the roof.","kw":["maximum height","low bridge","headroom","höjd"],"img":"C17-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransad-fordonshojd/","related":[]},{"id":"C18","cat":"C","sv":"Begränsad fordonslängd","en":"Length limit","svText":"Märket anger förbud mot trafik med fordon eller fordonståg över en viss längd. Längsta tillåtna längd anges på märket.","enText":"Vehicles or vehicle combinations longer than the length shown on the sign are prohibited.","tip":"","kw":["maximum length","längd"],"img":"C18-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransad-fordonslangd/","related":[]},{"id":"C19","cat":"C","sv":"Minsta avstånd","en":"Minimum distance","svText":"Märket anger förbud mot att hålla kortare avstånd till framförvarande motordrivna fordon i samma färdriktning än som anges på märket. Minsta tillåtna avstånd anges på märket.","enText":"It is prohibited to keep a shorter distance than the one shown to the motor vehicle in front of you going in the same direction.","tip":"","kw":["keep distance","following distance","avstånd","bridge"],"img":"C19-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/minsta-avstand/","related":[]},{"id":"C20","cat":"C","sv":"Begränsad bruttovikt på fordon","en":"Weight limit for a vehicle","svText":"Högsta tillåtna bruttovikt anges på märket.","enText":"Vehicles whose gross weight (the actual weight at that moment, load included) is higher than the weight shown are prohibited.","tip":"Gross weight (bruttovikt) is what the vehicle actually weighs right now. Total weight (totalvikt) is the highest weight it is registered for. These weight signs are about gross weight.","kw":["weight limit","bruttovikt","tonnes","bridge"],"img":"C20-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransad-bruttovikt-pa-fordon/","related":["C21"]},{"id":"C21","cat":"C","sv":"Begränsad bruttovikt på fordon och fordonståg","en":"Weight limit for a vehicle or combination","svText":"Högsta tillåtna bruttovikt anges på märket.","enText":"Vehicles and vehicle combinations whose gross weight (actual weight, load included) is higher than the weight shown are prohibited.","tip":"","kw":["weight limit","combination","trailer","bruttovikt"],"img":"C21-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransad-bruttovikt-pa-fordon-och-fordonstag/","related":["C20"]},{"id":"C22","cat":"C","sv":"Bärighetsklass","en":"Bearing capacity class","svText":"Vägens bärighetsklass anges på märket.","enText":"Shows the road's bearing capacity class (BK), which sets the highest axle, bogie and gross weights allowed. It matters mostly for heavy vehicles.","tip":"","kw":["BK1","BK2","BK3","bärighetsklass","weight class"],"img":"C22-3","variants":[{"key":"C22-2","en":"Bearing capacity class 2 (BK2). The main image shows BK3."}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/barighetsklass/","related":[]},{"id":"C23","cat":"C","sv":"Begränsat axeltryck","en":"Axle load limit","svText":"Högsta tillåtna axeltryck anges på märket.","enText":"The highest axle load allowed (the weight the wheels on one axle put on the road) is shown on the sign.","tip":"","kw":["axle weight","axeltryck"],"img":"C23-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransat-axeltryck/","related":[]},{"id":"C24","cat":"C","sv":"Begränsat boggitryck","en":"Bogie load limit","svText":"Högsta tillåtna boggitryck anges på märket.","enText":"The highest bogie load allowed (the weight that two axles less than 2 metres apart put on the road) is shown on the sign.","tip":"","kw":["bogie weight","boggitryck"],"img":"C24-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransat-boggitryck/","related":[]},{"id":"C25","cat":"C","sv":"Förbud mot sväng i korsning","en":"No turning","svText":"Förbudet gäller den korsning eller motsvarande som märket är placerat i eller före. Märket kan avse flera korsningar. Sträckans längd anges då på en tilläggstavla. Symbolen är anpassad efter förhållandena på platsen.","enText":"Turning in the direction shown is prohibited at the junction (or similar place) where the sign stands or that it is placed before. It can cover several junctions; the length of the stretch is then shown on a panel. The symbol is drawn to match the place.","tip":"","kw":["no left turn","no right turn","sväng förbjuden"],"img":"C25-1","variants":[{"key":"C25-2","en":"No right turn (the main image shows no left turn)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-svang-i-korsning/","related":["C26"]},{"id":"C26","cat":"C","sv":"Förbud mot U-sväng","en":"No U-turns","svText":"Förbudet gäller den korsning eller motsvarande som märket är placerat i eller före. Märket kan avse flera korsningar. Sträckans längd anges då på en tilläggstavla. Symbolen är anpassad efter förhållandena på platsen.","enText":"U-turns are prohibited at the junction (or similar place) where the sign stands or that it is placed before. It can cover several junctions; the length of the stretch is then shown on a panel.","tip":"","kw":["no u-turn","turning around","vändning"],"img":"C26-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-u-svang/","related":["C25"]},{"id":"C27","cat":"C","sv":"Förbud mot omkörning","en":"No overtaking","svText":"Märket anger förbud mot att köra om andra motordrivna fordon än tvåhjuliga mopeder och tvåhjuliga motorcyklar utan sidvagn. Förbudet gäller på den väg märket är uppsatt och till den plats där märke C28, slut på förbud mot omkörning, är uppsatt.","enText":"It is prohibited to overtake motor vehicles other than two-wheeled mopeds and two-wheeled motorcycles without a sidecar. The ban applies on the road where the sign is placed, until sign C28 (end of no overtaking).","tip":"You may still overtake a bicycle, a two-wheeled moped or a two-wheeled motorcycle without a sidecar, if it can be done safely.","kw":["overtaking prohibited","passing","omkörning förbjuden"],"img":"C27-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-omkorning/","related":["C28","C29"]},{"id":"C28","cat":"C","sv":"Slut på förbud mot omkörning","en":"End of no overtaking","svText":"","enText":"Marks the end of the overtaking ban that started with sign C27.","tip":"","kw":["overtaking allowed again"],"img":"C28-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/slut-pa-forbud-mot-omkorning/","related":["C27"]},{"id":"C29","cat":"C","sv":"Förbud mot omkörning med tung lastbil","en":"No overtaking by heavy trucks","svText":"Märket anger förbud mot att med en tung lastbil köra om andra motordrivna fordon än tvåhjuliga mopeder och tvåhjuliga motorcyklar utan sidvagn. Förbudet gäller på den väg märket är uppsatt till den plats där märke C30, slut på förbud mot omkörning med tung lastbil, är uppsatt.","enText":"Drivers of heavy trucks may not overtake motor vehicles other than two-wheeled mopeds and two-wheeled motorcycles without a sidecar. The ban applies until sign C30.","tip":"","kw":["lorry overtaking ban","lastbil"],"img":"C29-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-omkorning-med-tung-lastbil/","related":["C27","C30"]},{"id":"C30","cat":"C","sv":"Slut på förbud mot omkörning med tung lastbil","en":"End of no overtaking by heavy trucks","svText":"","enText":"Marks the end of the overtaking ban for heavy trucks that started with sign C29.","tip":"","kw":["heavy truck overtaking"],"img":"C30-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/slut-pa-forbud-mot-omkorning-med-tung-lastbil/","related":["C29"]},{"id":"C31","cat":"C","sv":"Hastighetsbegränsning","en":"Speed limit","svText":"Märket anger förbud mot att föra fordon med högre hastighet än den som anges på märket. Angivelsen gäller till den plats där en annan hastighetsbegränsning anges med märket, eller där märke C32, tillfällig hastighetsbegränsning upphör, E7, gågata, eller E9, gångfartsområde, satts upp. Märket behöver inte vara upprepat efter en vägkorsning om samma högsta tillåtna hastighet gäller på den korsande vägen.","enText":"You may not drive faster than the speed shown, in km/h. The limit applies until another speed limit sign, sign C32 (end of temporary speed limit), sign E7 (pedestrian street) or sign E9 (walking-speed area). The sign does not have to be repeated after a junction if the crossing road has the same limit.","tip":"A speed limit is the highest speed allowed, not the right speed. You must always adapt your speed to the conditions.","kw":["speed limit","km/h","hastighetsbegränsning","max speed",30,40,50,60,70,80,90,100,110,120],"img":"C31-3","variants":[{"key":"C31-4","en":"40 km/h"},{"key":"C31-5","en":"50 km/h"},{"key":"C31-6","en":"60 km/h"},{"key":"C31-7","en":"70 km/h"},{"key":"C31-8","en":"80 km/h"},{"key":"C31-9","en":"90 km/h"},{"key":"C31-10","en":"100 km/h"},{"key":"C31-11","en":"110 km/h"},{"key":"C31-12","en":"120 km/h"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/hastighetsbegransning/","related":["C32","E11"]},{"id":"C32","cat":"C","sv":"Tillfällig hastighetsbegränsning upphör","en":"End of temporary speed limit","svText":"Märket anger att en tillfällig hastighet som märkts ut med märke C31, hastighetsbegränsning, upphör.","enText":"Marks the end of a temporary speed limit that was shown with sign C31. After it, the speed limit that applied before the temporary limit applies again.","tip":"","kw":["end of speed limit","temporary speed limit","road works"],"img":"C32-3","variants":[{"key":"C32-2","en":"End of temporary 20 km/h"},{"key":"C32-4","en":"End of temporary 40 km/h"},{"key":"C32-5","en":"End of temporary 50 km/h"},{"key":"C32-6","en":"End of temporary 60 km/h"},{"key":"C32-7","en":"End of temporary 70 km/h"},{"key":"C32-8","en":"End of temporary 80 km/h"},{"key":"C32-9","en":"End of temporary 90 km/h"},{"key":"C32-10","en":"End of temporary 100 km/h"},{"key":"C32-11","en":"End of temporary 110 km/h"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/tillfallig-hastighetsbegransning-upphor/","related":["C31"]},{"id":"C33","cat":"C","sv":"Stopp vid tull","en":"Stop at customs","svText":"","enText":"You must stop for customs formalities, at the stop line or, if there is none, at the sign. The text below the bar is given in a suitable language.","tip":"","kw":["customs","border","tull"],"img":"C33-1","variants":[{"key":"C33-2","en":"Customs in Swedish and Norwegian"},{"key":"C33-3","en":"Customs in Swedish and Finnish"},{"key":"C33-4","en":"Customs in Swedish and German"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/stopp-vid-tull/","related":[]},{"id":"C34","cat":"C","sv":"Stopp för angivet ändamål","en":"Stop for the reason given","svText":"Märket anger skyldighet att stanna av den anledning som anges under det vågräta strecket. Om märket är uppsatt före en trafiksignal, anger det att fordon som ska passera signalen ska stanna vid röd signalbild. Fordonet ska stannas vid en stopplinje eller, om sådan saknas, vid märket. Transportstyrelsen får meddela föreskrifter om vilka andra anledningar som får anges.","enText":"You must stop for the reason written below the bar – at the stop line or, if there is none, at the sign. If the sign stands before a traffic signal (STOPP SIGNAL), vehicles that are to pass the signal must stop when it shows red.","tip":"","kw":["stop signal","ferry","police check","control"],"img":"C34","variants":[{"key":"C34-3","en":"STOPP FÄRJA – stop for the ferry"},{"key":"C34-4","en":"STOPP KONTROLL – stop for an inspection or check"},{"key":"C34-5","en":"STOPP VAKT – stop for a guard (for example at road works)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/stopp-for-angivet-andamal/","related":[]},{"id":"C35","cat":"C","sv":"Förbud mot att parkera fordon","en":"No parking","svText":"Märket anger förbud mot att parkera fordon. Angivelsen gäller på den sida av vägen där märket är uppsatt. Angivelsen börjar gälla där märket satts upp och gäller enligt vad som anges på en tilläggstavla, till den plats där någon annan bestämmelse om stannande eller parkering märkts ut, till nästa korsning med en annan väg än sådan som avses i 3 kap. 21 § andra stycket trafikförordningen (1998:1276) eller till den plats dessförinnan där ett motsvarande märke med tilläggstavla T11, utsträckning, med nedåtriktad pil, har satts upp. Om en annan bestämmelse gäller på en kortare sträcka gäller angivelsen på nytt efter sträckans slut utan att det upprepas. Angivelsen gäller också på nytt utan att märket satts upp igen i det fall en parkeringsplats anordnats vid sidan av körbanan. Märket anger inte rätt att stanna där fordon inte får stannas eller parkeras enligt trafikförordningen, om inte detta tydligt framgår av märkets placering eller anges på en tilläggstavla.","enText":"Parking is prohibited on the side of the road where the sign stands. The ban starts at the sign and applies as shown on a panel, or until another stopping or parking rule is signed, until the next junction, or until a matching sign with panel T11 (arrow pointing down). If another rule applies on a shorter stretch, the ban applies again after it without a new sign. The sign does not give you the right to stop where stopping is prohibited by the Road Traffic Ordinance.","tip":"You may still stop briefly, for example to let someone get in or out, or to load or unload.","kw":["no parking","parkering förbjuden","blue circle red line"],"img":"C35-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-att-parkera-fordon/","related":["C39","C36","C37","C38"]},{"id":"C36","cat":"C","sv":"Förbud mot att parkera fordon på dag med udda datum","en":"No parking on odd dates","svText":"De närmare föreskrifterna till märke C35, förbud mot att parkera fordon, gäller även till detta märke.","enText":"Parking is prohibited on days with an odd date (1st, 3rd, 5th …). Otherwise the same rules as for sign C35 apply.","tip":"","kw":["odd date","date parking"],"img":"C36-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-att-parkera-fordon-pa-dag-med-udda-datum/","related":["C37","C38","C35"]},{"id":"C37","cat":"C","sv":"Förbud mot att parkera fordon på dag med jämnt datum","en":"No parking on even dates","svText":"De närmare föreskrifterna till märke C35, förbud mot att parkera fordon, gäller även till detta märke.","enText":"Parking is prohibited on days with an even date (2nd, 4th, 6th …). Otherwise the same rules as for sign C35 apply.","tip":"","kw":["even date","date parking"],"img":"C37-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-att-parkera-fordon-pa-dag-med-jamnt-datum/","related":["C36","C38","C35"]},{"id":"C38","cat":"C","sv":"Datumparkering","en":"Date parking","svText":"Märket anger förbud mot att parkera fordon på dagar med jämnt datum på den sida av vägen som har jämna adressnummer och på dagar med udda datum på den sida av vägen som har udda adressnummer. De närmare föreskrifterna till märke C35, förbud mot att parkera fordon, gäller även till detta märke.","enText":"Parking is prohibited on days with an even date on the side of the road with even house numbers, and on days with an odd date on the side with odd house numbers. Otherwise the same rules as for sign C35 apply.","tip":"","kw":["date parking","datumparkering","house numbers"],"img":"C38-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/datumparkering/","related":["C36","C37"]},{"id":"C39","cat":"C","sv":"Förbud mot att stanna och parkera fordon","en":"No stopping or parking","svText":"Märket anger förbud mot att stanna och parkera fordon. De närmare föreskrifterna till märke C35, förbud mot att parkera fordon, andra stycket gäller även till detta märke.","enText":"Both stopping and parking are prohibited. The same rules as for sign C35 apply to where the ban starts and ends.","tip":"Here you may not even stop to let a passenger out. You may only stop if the traffic forces you to or to avoid danger.","kw":["no stopping","clearway","stoppförbud","red cross"],"img":"C39-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-att-stanna-och-parkera-fordon/","related":["C35"]},{"id":"C40","cat":"C","sv":"Ändamålsplats","en":"Special-purpose place","svText":"Har ändamålet angetts med lastplats är ändamålet lastning eller lossning av tungt eller skrymmande gods. Transportstyrelsen får meddela föreskrifter om vilka andra ändamål som får anges och hur de anges.","enText":"A place reserved for a stated purpose. Vehicles may not park or stop there except for that purpose, but may stop briefly to let people get in or out if this does not hinder the purpose. If the purpose is given as lastplats, it means loading or unloading of heavy or bulky goods.","tip":"","kw":["loading bay","lastplats","taxi","ändamålsplats"],"img":"C40-1","variants":[{"key":"C40-2","en":"Taxiplats – taxi place"},{"key":"C40-3","en":"Bokbussplats – mobile library bus place"},{"key":"C40-4","en":"Ambulansplats – ambulance place"},{"key":"C40-5","en":"Skolskjutsplats – school transport place"},{"key":"C40-6","en":"På- och avstigningsplats – place for getting in and out"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/andamalsplats/","related":["C41"]},{"id":"C41","cat":"C","sv":"Slut på ändamålsplats","en":"End of special-purpose place","svText":"Märket behöver inte vara uppsatt om det ändå tydligt framgår att ändamålsplatsen upphör. Märket är anpassat till märke C40, ändamålsplats.","enText":"Marks the end of a special-purpose place (sign C40). It is left out if it is clear anyway where the place ends.","tip":"","kw":["end of loading bay"],"img":"C41-1","variants":[{"key":"C41-2","en":"End of taxi place"},{"key":"C41-3","en":"End of mobile library bus place"},{"key":"C41-4","en":"End of ambulance place"},{"key":"C41-5","en":"End of school transport place"},{"key":"C41-6","en":"End of place for getting in and out"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/slut-pa-andamalsplats/","related":["C40"]},{"id":"C42","cat":"C","sv":"Vändplats","en":"Turning place","svText":"Märket anger en plats som är avsedd för vändning av fordon och att det är förbjudet att parkera fordon. Om i stället märke C39, förbud mot att stanna och parkera fordon, är infogat i märket anger det att det är förbjudet att stanna eller parkera fordon.","enText":"Marks a place meant for turning vehicles around, where parking is prohibited. If the no-stopping symbol (C39) is shown in the sign instead, both stopping and parking are prohibited.","tip":"","kw":["turning area","vändplats"],"img":"C42-1","variants":[{"key":"C42-2","en":"Turning place where stopping and parking are prohibited"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/vandplats/","related":["C43"]},{"id":"C43","cat":"C","sv":"Slut på vändplats","en":"End of turning place","svText":"Märket behöver inte vara uppsatt om det ändå tydligt framgår att vändplatsen upphör. Märket är anpassat till märke C42, vändplats.","enText":"Marks the end of a turning place (sign C42). It is left out if it is clear anyway where it ends.","tip":"","kw":["end of turning area"],"img":"C43-1","variants":[{"key":"C43-2","en":"End of a turning place where stopping was prohibited"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/slut-pa-vandplats/","related":["C42"]},{"id":"C44","cat":"C","sv":"Förbud mot trafik med annat motordrivet fordon med dubbdäck än moped klass II","en":"No motor vehicles with studded tyres","svText":"Avser förbudet även moped klass II anges det på en tilläggstavla.","enText":"Traffic with motor vehicles that have studded tyres is prohibited, except class II mopeds. If class II mopeds are also banned, a panel says so.","tip":"Some city streets ban studded tyres to reduce road wear and harmful particles in the air.","kw":["studded tyres","dubbdäck","spikes","winter tyres"],"img":"C44","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/forbud-mot-trafik-med-annat-motordrivet-fordon-med-dubbdack-an-moped-klass-ii/","related":[]},{"id":"C45","cat":"C","sv":"Särskilda bestämmelser för stannande och parkering","en":"Special rules for stopping and parking","svText":"Märket anger det förbud som anges med det infogade märket. Märket kan också ange avvikelse från den reglering som anges med det märke som den är uppsatt under. Andra förbud kan anges med märket. Transportstyrelsen får meddela föreskrifter om vilka andra förbudsmärken som får infogas. Märket är uppsatt under något av märkena C35, förbud mot att parkera fordon, C36, förbud mot att parkera fordon på dag med udda datum, C37, förbud mot att parkera fordon på dag med jämnt datum, C38, datumparkering, C39, förbud mot att stanna och parkera fordon, C40, ändamålsplats, C42, vändplats, D10, påbjudet körfält eller körbana för fordon i linjetrafik m.fl., E19, parkering eller E20, områdesmärke. Märke E20, områdesmärke, får vara infogat. Är märket infogat gäller de närmare föreskrifterna till märke E20, områdesmärke. För tid gäller de närmare föreskrifterna för tilläggstavla T6, tidsangivelse. Andra begränsningar kan endast vara angivna på märket.","enText":"A panel that contains a small prohibitory sign and conditions, for example times. It applies the ban shown inside it, or it gives an exception to the sign it is placed under. Times work as on panel T6. It is placed under signs such as C35–C40, C42, D10, E19 or E20.","tip":"","kw":["parking times","parking rules panel"],"img":"C45","variants":[{"key":"C45-2","en":"No parking during the times shown"},{"key":"C45-3","en":"No parking on odd dates during the times shown"},{"key":"C45-4","en":"No parking on even dates during the times shown"},{"key":"C45-5","en":"Date parking during the times shown"},{"key":"C45-6","en":"No stopping or parking during the times shown"},{"key":"C45-7","en":"No stopping or parking during the times shown"},{"key":"C45-8","en":"The same panel with the no-parking symbol inside a square frame"},{"key":"C45-9","en":"The same panel with the date-parking symbol inside a square frame"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/sarskilda-bestammelser-for-stannande-och-parkering/","related":[]},{"id":"C46","cat":"C","sv":"Begränsat trippelaxeltryck","en":"Triple axle load limit","svText":"Högsta tillåtna trippelaxeltryck anges på märket.","enText":"The highest triple axle load allowed (the weight that three axles close together put on the road) is shown on the sign.","tip":"","kw":["triple axle","trippelaxeltryck"],"img":"C46","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/forbudsmarken/begransat-trippelaxeltryck/","related":[]},{"id":"D1","cat":"D","sv":"Påbjuden körriktning","en":"Mandatory direction","svText":"Märket anger att fordon endast får föras i pilens eller, där två pilar finns, i endera pilens riktning. Symbolen är anpassad efter förhållandena på platsen.","enText":"Vehicles may only be driven in the direction of the arrow, or, where there are two arrows, in the direction of either arrow. The symbol is drawn to match the place.","tip":"","kw":["compulsory direction","one way","arrow","påbjuden körriktning"],"img":"D1-1","variants":[{"key":"D1-2","en":"Drive to the right"},{"key":"D1-3","en":"Drive straight ahead"},{"key":"D1-4","en":"Turn left"},{"key":"D1-5","en":"Turn right"},{"key":"D1-6","en":"Straight ahead or left"},{"key":"D1-7","en":"Straight ahead or right"},{"key":"D1-8","en":"Left or right"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-korriktning/","related":["D2","E16"]},{"id":"D2","cat":"D","sv":"Påbjuden körbana","en":"Pass this side","svText":"Märkena anger att fordon endast får föras förbi märket där pilen visar eller, där två pilar finns, där pilarna visar. Symbolen är anpassad efter förhållandena på platsen.","enText":"Vehicles may only pass the sign on the side the arrow points to, or where there are two arrows, on either side. The symbol is drawn to match the place.","tip":"","kw":["keep right","keep left","traffic island","refuge"],"img":"D2-1","variants":[{"key":"D2-2","en":"Pass on the left"},{"key":"D2-3","en":"Pass on either side"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-korbana/","related":["D1"]},{"id":"D3","cat":"D","sv":"Cirkulationsplats","en":"Roundabout","svText":"","enText":"Marks a roundabout (cirkulationsplats). Drive anticlockwise around the centre, and give way to every vehicle already in the roundabout when you enter.","tip":"","kw":["roundabout","rondell","cirkulationsplats"],"img":"D3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/cirkulationsplats/","related":["A30"]},{"id":"D4","cat":"D","sv":"Påbjuden cykelbana","en":"Cycle track","svText":"Om moped klass II inte får föras på banan anges det på en tilläggstavla.","enText":"Marks a track for cyclists (and class II mopeds unless a panel says otherwise). Other traffic is not allowed on it.","tip":"Drivers may cross a cycle track, for example to reach a property, but must give way to cyclists on it.","kw":["bike lane","bicycle path","cykelbana"],"img":"D4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-cykelbana/","related":["D6","D7","D11"]},{"id":"D5","cat":"D","sv":"Påbjuden gångbana","en":"Footpath","svText":"Märket anger bana avsedd endast för gående.","enText":"Marks a path for pedestrians only.","tip":"","kw":["pedestrian path","gångbana","walkway"],"img":"D5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-gangbana/","related":["D6","D11"]},{"id":"D6","cat":"D","sv":"Påbjuden gång- och cykelbana","en":"Shared path for pedestrians and cyclists","svText":"Märket anger gemensam bana för gående och cyklande. Om moped klass II inte får föras på banan anges det på en tilläggstavla.","enText":"Marks a path shared by pedestrians and cyclists (and class II mopeds unless a panel says otherwise).","tip":"","kw":["shared path","gång- och cykelbana"],"img":"D6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-gang--och-cykelbana/","related":["D4","D7"]},{"id":"D7","cat":"D","sv":"Påbjudna gång- och cykelbanor","en":"Separated paths for pedestrians and cyclists","svText":"Märket anger banor som är delade genom vägmarkering, skiljeremsa eller liknande i en del för gående och en del för cyklande. Symbolernas placering på märket anger vilken del av banan som är avsedd för gående respektive cyklande. Om moped klass II inte får föras på banan anges det på en tilläggstavla.","enText":"Marks paths that are divided by a road marking, kerb or similar into one part for pedestrians and one for cyclists. The position of the symbols on the sign shows which side is for whom. Class II mopeds may use the cycle part unless a panel says otherwise.","tip":"","kw":["segregated path","split path"],"img":"D7-1","variants":[{"key":"D7-2","en":"Cyclists on the left, pedestrians on the right"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjudna-gang--och-cykelbanor/","related":["D6"]},{"id":"D8","cat":"D","sv":"Påbjuden ridväg","en":"Bridle path","svText":"Märket anger även att gångtrafik är tillåten.","enText":"Marks a path for horse riding. Walking is also allowed on it.","tip":"","kw":["riding path","ridväg","horses"],"img":"D8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-ridvag/","related":[]},{"id":"D9","cat":"D","sv":"Påbjuden led för terrängmotorfordon och terrängsläp","en":"Route for off-road vehicles","svText":"Märket anger även att gångtrafik är tillåten.","enText":"Marks a route for off-road motor vehicles (such as snowmobiles) and off-road trailers. Walking is also allowed on it.","tip":"","kw":["snowmobile trail","skoterled"],"img":"D9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-led-for-terrangmotorfordon-och-terrangslap/","related":[]},{"id":"D10","cat":"D","sv":"Påbjudet körfält eller körbana för fordon i linjetrafik med flera","en":"Bus lane","svText":"Märket anger även att fordon som anges i 8 kap. 2 § trafikförordningen (1998:1276) får använda körfältet eller körbanan, om inte annat anges på en tilläggstavla. Om andra fordon tillåts trafikera körfältet eller körbanan anges det på en tilläggstavla.","enText":"Marks a lane or carriageway for vehicles in scheduled services (buses) and the others allowed by the Road Traffic Ordinance – bicycles and class II mopeds may use it if it is on the right-hand side. A panel can allow other vehicles, such as taxis.","tip":"Other drivers may only cross a bus lane, for example to turn. Watch the panel – it may allow taxis or set times.","kw":["bus lane","kollektivkörfält","linjetrafik","public transport"],"img":"D10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjudet-korfalt-eller-korbana-for-fordon-i-linjetrafik-mfl/","related":["D11"]},{"id":"D11","cat":"D","sv":"Slut på påbjuden bana, körfält, väg eller led","en":"End of compulsory path, lane or route","svText":"Märket anger att påbjuden bana, körfält, väg eller led som märkts ut med något av märkena D4-D10 upphör. Märket behöver inte sättas upp om det ändå tydligt framgår att påbudet upphör. Andra symboler för trafikantgrupper eller fordonsslag kan vara infogade i märket. Den symbol som är infogad i märket är samma som på det märke som använts för att märka ut banan, körfältet, vägen eller leden.","enText":"Marks the end of a path, lane, road or route marked with one of the signs D4–D10. It is left out if it is clear anyway that the rule has ended. The symbol in it is the same as on the sign that started the stretch.","tip":"","kw":["end of bus lane","end of cycle track"],"img":"D11-1","variants":[{"key":"D11-2","en":"End of cycle track"},{"key":"D11-3","en":"End of footpath"},{"key":"D11-4","en":"End of shared path"},{"key":"D11-5","en":"End of separated paths (pedestrians left, cyclists right)"},{"key":"D11-6","en":"End of separated paths (cyclists left, pedestrians right)"},{"key":"D11-7","en":"End of bridle path"},{"key":"D11-8","en":"End of route for off-road vehicles"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/slut-pa-pabjuden-bana-korfalt-vag-eller-led/","related":[]},{"id":"D12","cat":"D","sv":"Påbjuden körriktning för fordon lastat med farligt gods","en":"Mandatory direction for vehicles with dangerous goods","svText":"Märket anger påbjuden körriktning för trafik med fordon med sådan last som omfattas av krav på märkning med orangefärgad skylt enligt föreskrifter som har meddelats med stöd av lagen (2006:263) om transport av farligt gods. Bokstaven på märket anger att påbudet endast avser sådana fordon som inte får framföras i en vägtunnel som tillhör den tunnelkategori som motsvarar bokstaven.","enText":"Shows the direction that vehicles carrying dangerous goods (marked with orange plates) must take. A letter on the sign means the rule only applies to vehicles that may not go through a tunnel of that category.","tip":"","kw":["dangerous goods route","ADR"],"img":"D12-1","variants":[{"key":"D12-2","en":"The same sign for vehicles that may not pass a category B tunnel"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/pabudsmarken/pabjuden-korriktning-for-fordon-lastat-med-farligt-gods/","related":["C9"]},{"id":"E1","cat":"E","sv":"Motorväg","en":"Motorway","svText":"Används märket som förberedande upplysning om att en motorväg börjar anges avståndet på en tilläggstavla. Märket kan även vara infogat i ett lokaliseringsmärke.","enText":"Marks the start of a motorway (motorväg), where the special motorway rules apply. Used as an advance notice, a panel gives the distance to where the motorway begins. The sign can also appear inside a direction sign.","tip":"On a motorway the speed limit is 110 km/h unless signs show otherwise, and you may not stop, park, turn around or reverse.","kw":["motorway","highway","freeway","motorväg","green sign"],"img":"E-11","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/motorvag/","related":["E2","E3"]},{"id":"E2","cat":"E","sv":"Motorväg upphör","en":"End of motorway","svText":"Används märket som förberedande upplysning om att en motorväg upphör anges avståndet på en tilläggstavla. Märket används inte när en motorväg övergår i motortrafikled.","enText":"Marks the end of a motorway. Used as an advance notice, a panel gives the distance. It is not used where a motorway turns into an expressway (motortrafikled).","tip":"","kw":["motorway ends"],"img":"E2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/motorvag-upphor/","related":["E1"]},{"id":"E3","cat":"E","sv":"Motortrafikled","en":"Expressway","svText":"Används märket som förberedande upplysning om att en motortrafikled börjar anges avståndet på en tilläggstavla. Märket kan även vara infogat i ett lokaliseringsmärke.","enText":"Marks the start of an expressway (motortrafikled) – a road for fast motor traffic with no level junctions, where most motorway rules apply. Used as an advance notice, a panel gives the distance. The sign can also appear inside a direction sign.","tip":"Unlike a motorway, an expressway may have traffic in both directions on the same carriageway without a central reserve. The motorway's 110 km/h default does not apply, so follow the speed limit signs.","kw":["expressway","motor traffic road","motortrafikled","green car sign"],"img":"E3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/motortrafikled/","related":["E4","E1"]},{"id":"E4","cat":"E","sv":"Motortrafikled upphör","en":"End of expressway","svText":"Används märket som förberedande upplysning om att en motortrafikled upphör anges avståndet på en tilläggstavla. Märket används inte när en motortrafikled övergår i motorväg.","enText":"Marks the end of an expressway. Used as an advance notice, a panel gives the distance. It is not used where an expressway turns into a motorway.","tip":"","kw":["expressway ends"],"img":"E4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/motortrafikled-upphor/","related":["E3"]},{"id":"E5","cat":"E","sv":"Tättbebyggt område","en":"Built-up area","svText":"Ortnamnet kan vara infogat i märket.","enText":"Marks the start of a built-up area (tättbebyggt område). The name of the place may be shown on the sign.","tip":"In a built-up area the speed limit is 50 km/h unless signs show otherwise. A prohibitory sign put up together with this sign applies in the whole built-up area.","kw":["town","village","city limit","tättbebyggt område"],"img":"E5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/tattbebyggt-omrade/","related":["E6"]},{"id":"E6","cat":"E","sv":"Tättbebyggt område upphör","en":"End of built-up area","svText":"Ortnamnet kan vara infogat i märket.","enText":"Marks the end of a built-up area. The name of the place may be shown on the sign.","tip":"After this sign the base speed of 70 km/h applies unless another limit is signed.","kw":["leaving town","end of town"],"img":"E6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/tattbebyggt-omrade-upphor/","related":["E5"]},{"id":"E7","cat":"E","sv":"Gågata","en":"Pedestrian street","svText":"Märket anger att bestämmelserna i 8 kap. 1 § trafikförordningen (1998:1276) är tillämpliga. Förbud mot att föra fordon som får föras på gågata enligt 8 kap. 1 § andra stycket trafikförordningen anges på en tilläggstavla.","enText":"Marks a pedestrian street (gågata). Vehicles may drive at walking speed only, may not park, and must give way to pedestrians. Motor vehicles may only cross it, except for deliveries to shops, transport of goods or residents to and from addresses, transport of hotel guests, and transport of sick or disabled people. A panel can prohibit even that traffic.","tip":"","kw":["pedestrian zone","walking street","gågata"],"img":"E7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/gagata/","related":["E8","E9"]},{"id":"E8","cat":"E","sv":"Gågata upphör","en":"End of pedestrian street","svText":"Märket behöver inte vara uppsatt om det ändå tydligt framgår att gågatan upphör.","enText":"Marks the end of a pedestrian street. It is left out if it is clear anyway where the street ends.","tip":"","kw":["pedestrian zone ends"],"img":"E8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/gagata-upphor/","related":["E7"]},{"id":"E9","cat":"E","sv":"Gångfartsområde","en":"Walking-speed area","svText":"Märket anger att bestämmelserna i 8 kap. 1 § första stycket trafikförordningen är tillämpliga.","enText":"Marks a walking-speed area (gångfartsområde). Vehicles may drive at walking speed only, may not park, and must give way to pedestrians.","tip":"Unlike a pedestrian street, motor vehicles may drive in a walking-speed area – but only at walking speed and always giving way to pedestrians. Children may play in the street.","kw":["shared space","home zone","woonerf","gångfartsområde"],"img":"E9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/gangfartsomrade/","related":["E10","E7"]},{"id":"E10","cat":"E","sv":"Gångfartsområde upphör","en":"End of walking-speed area","svText":"Märket behöver inte vara uppsatt om det ändå tydligt framgår att gångfartsområdet upphör.","enText":"Marks the end of a walking-speed area. It is left out if it is clear anyway where the area ends.","tip":"","kw":["end of home zone"],"img":"E10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/gangfartsomrade-upphor/","related":["E9"]},{"id":"E11","cat":"E","sv":"Rekommenderad lägre hastighet","en":"Recommended lower speed","svText":"Märket anger en vägsträcka eller ett område där särskilda åtgärder vidtagits eller där förhållandena är sådana att det är lämpligt att färdas med lägre hastighet än den högsta tillåtna. Den rekommenderade lägre hastigheten anges på märket.","enText":"Marks a stretch or an area where special measures have been taken, or where conditions make it suitable to drive slower than the speed limit. The recommended speed is shown on the sign.","tip":"This blue sign is advice, not a legal limit like the red-ringed C31. It is still wise to follow it.","kw":["recommended speed","advisory speed","max km/tim"],"img":"E11-1","variants":[{"key":"E11-2","en":"The same sign with another recommended speed"},{"key":"E11-3","en":"The same sign with another recommended speed"},{"key":"E11-4","en":"The same sign with another recommended speed"},{"key":"E11-5","en":"The same sign with another recommended speed"},{"key":"E11-6","en":"The same sign with another recommended speed"},{"key":"E11-7","en":"The same sign with another recommended speed"},{"key":"E11-8","en":"The same sign with another recommended speed"},{"key":"E11-9","en":"The same sign with another recommended speed"},{"key":"E11-10","en":"The same sign with another recommended speed"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/rekommenderad-lagre-hastighet/","related":["E12","C31","E13"]},{"id":"E12","cat":"E","sv":"Rekommenderad lägre hastighet upphör","en":"End of recommended lower speed","svText":"Märket behöver inte vara uppsatt om det ändå tydligt framgår att sträckan upphör.","enText":"Marks the end of a stretch with a recommended lower speed. It is left out if it is clear anyway where the stretch ends.","tip":"","kw":["end of recommended speed"],"img":"E12-1","variants":[{"key":"E12-2","en":"The same sign for another recommended speed"},{"key":"E12-3","en":"The same sign for another recommended speed"},{"key":"E12-4","en":"The same sign for another recommended speed"},{"key":"E12-5","en":"The same sign for another recommended speed"},{"key":"E12-6","en":"The same sign for another recommended speed"},{"key":"E12-7","en":"The same sign for another recommended speed"},{"key":"E12-8","en":"The same sign for another recommended speed"},{"key":"E12-9","en":"The same sign for another recommended speed"},{"key":"E12-10","en":"The same sign for another recommended speed"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/rekommenderad-lagre-hastighet-upphor/","related":["E11"]},{"id":"E13","cat":"E","sv":"Rekommenderad högsta hastighet","en":"Recommended maximum speed","svText":"Märket används endast som omställbart vägmärke och anger att förhållandena tillfälligt är sådana att det inte är lämpligt att färdas med högre hastighet än den som anges på märket. Den angivna hastigheten är alltid lägre än den högsta tillåtna.","enText":"Used only as a variable (electronic) sign. It shows that conditions are temporarily such that it is not suitable to drive faster than the speed shown, for example because of queues, an accident or bad weather. The speed shown is always lower than the speed limit.","tip":"","kw":["variable speed","electronic sign","motorway sign"],"img":"E13-1","variants":[{"key":"E13-2","en":"The same sign showing another speed"},{"key":"E13-3","en":"The same sign showing another speed"},{"key":"E13-4","en":"The same sign showing another speed"},{"key":"E13-5","en":"The same sign showing another speed"},{"key":"E13-6","en":"The same sign showing another speed"},{"key":"E13-7","en":"The same sign showing another speed"},{"key":"E13-8","en":"The same sign showing another speed"},{"key":"E13-9","en":"The same sign showing another speed"},{"key":"E13-10","en":"The same sign showing another speed"},{"key":"E13-11","en":"The same sign showing another speed"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/rekommenderad-hogsta-hastighet/","related":["E14","E11","C31"]},{"id":"E14","cat":"E","sv":"Rekommenderad högsta hastighet upphör","en":"End of recommended maximum speed","svText":"Märket behöver inte vara uppsatt om det ändå tydligt framgår att de tillfälliga förhållandena upphört.","enText":"Shows that the temporary conditions behind a recommended maximum speed (E13) have ended. It is left out if that is clear anyway.","tip":"","kw":["end of advisory speed"],"img":"E14-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/rekommenderad-hogsta-hastighet-upphor/","related":["E13"]},{"id":"E15","cat":"E","sv":"Sammanvävning","en":"Merging lanes (zip merge)","svText":"Märket upplyser om att två körfält eller körbanor löper samman och att förarna ska anpassa sig till de nya förhållandena på platsen enligt bestämmelserna i 3 kap. 44 § trafikförordningen. Märket används även som förberedande upplysning om att två körfält eller körbanor löper samman. Avståndet anges då på en tilläggstavla.","enText":"Informs that two lanes or two carriageways run together and that drivers must adapt to each other (chapter 3, section 44 of the Road Traffic Ordinance). It is also used in advance, with the distance on a panel.","tip":"Where lanes merge, nobody has priority. Drivers take turns, one from each lane, like a zip – this is called sammanvävning.","kw":["zip merge","merging","lanes merge","sammanvävning","zipper"],"img":"E15-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/sammanvavning/","related":["F17"]},{"id":"E16","cat":"E","sv":"Enkelriktad trafik","en":"One-way traffic","svText":"Märket anger att fordonstrafiken på vägen är enkelriktad i pilens riktning. Uppåtriktad pil anger att trafiken är enkelriktad i riktning rakt fram.","enText":"Shows that vehicle traffic on the road goes one way only, in the direction of the arrow. An upward arrow means traffic goes one way straight ahead.","tip":"","kw":["one way street","enkelriktad"],"img":"E16-1","variants":[{"key":"E16-2","en":"One-way traffic straight ahead (upward arrow)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/enkelriktad-trafik/","related":["C1","D1"]},{"id":"E17","cat":"E","sv":"Återvändsväg E17","en":"Dead end","svText":"Märket anger att genomfart inte är möjlig. Symbolen anpassas efter förhållandena på platsen och kan vara infogad i ett lokaliseringsmärke. Om genomfart med cykel och moped klass II är möjlig anges det genom att symbol S8, cykel och moped klass II, är infogad i märket.","enText":"Shows that you cannot drive through. The symbol is drawn to match the place and can be part of a direction sign. If cyclists and class II moped riders can get through, the bicycle symbol (S8) is added to the sign.","tip":"","kw":["no through road","cul-de-sac","återvändsväg"],"img":"E17-1","variants":[{"key":"E17-2","en":"Dead-end road to the right"},{"key":"E17-3","en":"Dead-end road to the left"},{"key":"E17-4","en":"Dead end, but bicycles and class II mopeds can get through"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/atervandsvag/","related":[]},{"id":"E18","cat":"E","sv":"Mötesplats","en":"Passing place","svText":"","enText":"Marks a passing place (mötesplats) on a narrow road, where vehicles can meet or let others overtake.","tip":"You may not park in a passing place marked with this sign.","kw":["meeting place","passing bay","M sign","mötesplats"],"img":"E18-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/motesplats/","related":[]},{"id":"E19","cat":"E","sv":"Parkering","en":"Parking","svText":"Märket anger att parkering är tillåten på en parkeringsplats eller på en sträcka på den sida av vägen där vägmärket är uppsatt. Är märket uppsatt vid en väg anger det att tillåtelsen börjar där märket har satts upp och gäller enligt vad som anges på en tilläggstavla, till den plats där en annan bestämmelse om stannande eller parkering märkts ut eller i annat fall till nästa korsning med en annan väg än sådan som avses i 3 kap. 21 § andra stycket trafikförordningen. Gäller sådan annan bestämmelse på en kortare sträcka gäller dock anvisningen på nytt efter sträckans slut utan att märket upprepas. Används märket vid en särskilt anordnad parkeringsplats gäller anvisningen hela parkeringsplatsen. Märket anger inte rätt att parkera där fordon enligt trafikförordningen inte får stannas eller parkeras, om inte en sådan rätt tydligt framgår av märkets placering eller anges på en tilläggstavla. Märket anger inte heller rätt att parkera fordon i strid mot 3 kap. 49 a § första stycket trafikförordningen. Används märket av en markägare enligt lagen (1984:318) om kontrollavgift vid olovlig parkering anger märket att parkering är tillåten, dock högst 24 timmar i följd vardagar utom vardag före sön- och helgdag, om inte annat framgår av en tilläggstavla. Märket kan vara infogat i ett lokaliseringsmärke. Om märket används som förberedande upplysning, kan uppgift om parkeringsplatsens namn, om att parkeringsplatsen är fullbelagd eller att det finns lediga platser lämnas i anslutning till märket.","enText":"Parking is allowed in a car park, or on a stretch on the side of the road where the sign stands. By a road, the permission starts at the sign and applies as a panel says, until another stopping or parking rule is signed, or else to the next junction. In a car park it covers the whole car park. It does not allow parking where the Road Traffic Ordinance forbids stopping or parking, and it does not allow parking longer than 24 hours in a row on weekdays on public streets and roads.","tip":"Look for panels under the P sign – they may set a time limit, fees, a parking disc or a vehicle type.","kw":["parking","P sign","car park","parkering"],"img":"E19-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/parkering/","related":["C35","E30"]},{"id":"E20","cat":"E","sv":"Områdesmärke","en":"Zone sign","svText":"Märket anger att ett område börjar med de förbud eller tillåtelser som anges med det infogade märket. Avvikelser från anvisningarna på märket kan anges genom tilläggstavlor. Tidsbegränsningar kan även infogas i märket. Märket är uppsatt vid infarterna till området och gäller till den plats där tavla E21, slut på område, är uppsatt eller det på annat tydligt sätt framgår att anvisningarna på märket inte gäller. Inom området kan det förekomma avvikelser från anvisningarna på märket. Dessa avvikelser anges genom andra vägmärken och tilläggstavlor. Anvisningarna på märket gäller även efter sådan avvikelse utan att märket upprepas. Andra förbud eller tillåtelser kan anges på märket. Transportstyrelsen får meddela föreskrifter om vilka andra vägmärken som får infogas.","enText":"Marks the start of an area (zone) where the prohibition or permission shown inside the sign applies. It stands at every entrance to the area and applies until sign E21 (end of zone) or until it is otherwise clear that it no longer applies. Exceptions inside the area are shown with other signs and panels, and the zone rule applies again after them without a new sign. Times can be shown in the sign.","tip":"","kw":["zone","area sign","områdesmärke","parking zone"],"img":"E20-1","variants":[{"key":"E20-2","en":"Zone with no vehicles"},{"key":"E20-3","en":"Zone with no motor vehicles (except class II mopeds)"},{"key":"E20-4","en":"Zone with no motor vehicles with more than two wheels"},{"key":"E20-5","en":"Zone with no vehicles towing a trailer"},{"key":"E20-7","en":"Zone with no tractors and class II motor implements"},{"key":"E20-8","en":"Zone with a height limit"},{"key":"E20-9","en":"Zone with a length limit"},{"key":"E20-10","en":"Zone with a weight limit for vehicles"},{"key":"E20-11","en":"Zone with a weight limit for vehicles and combinations"},{"key":"E20-12","en":"Zone with an axle load limit"},{"key":"E20-13","en":"Zone with a bogie load limit"},{"key":"E20-14","en":"Zone with no parking on even dates"},{"key":"E20-15","en":"Zone with no stopping or parking"},{"key":"E20-16","en":"Parking zone with a time limit (here 15 minutes)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/omradesmarke/","related":["E21"]},{"id":"E21","cat":"E","sv":"Slut på område","en":"End of zone","svText":"Märket anger att ett område med förbud eller tillåtelser som angetts med ett märke E20, områdesmärke, upphör. Utseendet är anpassat till det märke som infogats i märke E20, områdesmärke.","enText":"Marks the end of a zone that started with sign E20. It looks like the sign that was inside the E20 sign.","tip":"","kw":["end of zone"],"img":"E21-1","variants":[{"key":"E21-2","en":"End of zone with no vehicles"},{"key":"E21-3","en":"End of zone (other rule)"},{"key":"E21-4","en":"End of zone (other rule)"},{"key":"E21-5","en":"End of zone (other rule)"},{"key":"E21-6","en":"End of zone (other rule)"},{"key":"E21-7","en":"End of zone (other rule)"},{"key":"E21-8","en":"End of zone (other rule)"},{"key":"E21-9","en":"End of zone (other rule)"},{"key":"E21-10","en":"End of zone (other rule)"},{"key":"E21-11","en":"End of zone (other rule)"},{"key":"E21-12","en":"End of zone (other rule)"},{"key":"E21-13","en":"End of zone (other rule)"},{"key":"E21-14","en":"End of zone (other rule)"},{"key":"E21-15","en":"End of zone (other rule)"},{"key":"E21-16","en":"End of zone (other rule)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/slut-pa-omrade2/","related":["E20"]},{"id":"E22","cat":"E","sv":"Busshållplats","en":"Bus stop","svText":"Märket anger en hållplats för fordon i linjetrafik och skolskjuts om inte hållplatsen tydligt framgår på annat sätt. Trots bestämmelserna i 1 kap. 5 § kan uppgifter om busslinjer, bussföretag och motsvarande förekomma på eller vid märket. Klockslag kan anges på märket.","enText":"Marks a stop for buses in scheduled service and school transport, unless the stop is clearly shown in another way. Bus lines, operators and times may be shown on or by the sign.","tip":"Within 20 metres before and 5 metres after this sign (where no markings show the stop), other vehicles may only stop briefly to let passengers on or off without hindering buses. In built-up areas with a limit of 50 km/h or lower, let a bus that signals leave the stop first.","kw":["bus stop","busshållplats"],"img":"E22-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/busshallplats/","related":[]},{"id":"E23","cat":"E","sv":"Taxi","en":"Taxi rank","svText":"Märket anger den, i färdriktningen, bortre gränsen för en särskild uppställningsplats för fordon som används i taxitrafik.","enText":"Marks the far end (in the direction of travel) of a special place where taxis wait.","tip":"","kw":["taxi stand","taxi rank"],"img":"E23-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/taxi2/","related":[]},{"id":"E24","cat":"E","sv":"Automatisk trafikövervakning","en":"Automatic traffic surveillance","svText":"Märket anger att automatisk övervakning med kamera eller motsvarande kan ske på en plats eller vägsträcka för övervakning av trafikregler, beskattning eller avgiftsbeläggning. Märket anger vidare att personuppgifter kan registreras enligt Dataskyddsförordningen, lagen (2001:558) om vägtrafikregister eller någon annan registerlag. Gäller anvisningen en längre vägsträcka, anges sträckans längd på tilläggstavla T1, vägsträckas längd. Märket upprepas på lämpliga avstånd.","enText":"Shows that automatic monitoring with a camera or similar may take place at the spot or along the stretch – to check traffic rules (for example speed), or for taxes or fees. Personal data may be recorded. For a longer stretch, the length is shown on panel T1, and the sign is repeated at suitable distances.","tip":"","kw":["speed camera","ATK","traffic camera","surveillance"],"img":"E24-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/automatisk-trafikovervakning/","related":[]},{"id":"E25","cat":"E","sv":"Betalväg","en":"Toll road or charge","svText":"Märket anger att avgift eller särskild skatt ska betalas vid färd på en viss väg eller inom ett visst område.","enText":"Shows that a fee or special tax must be paid to drive on a certain road or within a certain area, for example congestion tax or a bridge toll.","tip":"","kw":["toll","congestion charge","trängselskatt","infrastructure charge","betalväg"],"img":"E25-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/betalvag/","related":[]},{"id":"E26","cat":"E","sv":"Tunnel","en":"Tunnel","svText":"Märket anger tunnel. Tunnelns längd anges och tunnelns namn kan anges på märket. Märket är upprepat efter varje kilometer och kvarvarande tunnellängd anges då på märket.","enText":"Marks a tunnel. The length of the tunnel is shown, and its name may be shown. The sign is repeated after every kilometre, then showing the remaining length.","tip":"","kw":["tunnel length"],"img":"E26-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/tunnel/","related":["A26"]},{"id":"E27","cat":"E","sv":"Nöduppställningsplats","en":"Emergency lay-by","svText":"Märket anger plats för uppställning av fordon vid haveri, motorstopp eller liknande. Symbol för hjälptelefon eller brandsläckare kan vara infogad i märket. Märket är utformat efter förhållandena på platsen. Används märket som förberedande upplysning om nöduppställningsplats anges avståndet på en tilläggstavla.","enText":"Marks a place to stop a vehicle after a breakdown, engine failure or similar. A symbol for an emergency telephone or a fire extinguisher may be added. With a panel showing distance, it gives advance notice.","tip":"","kw":["emergency stopping place","breakdown bay","SOS"],"img":"E27-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/noduppstallningsplats/","related":[]},{"id":"E28","cat":"E","sv":"Nödutgång","en":"Emergency exit","svText":"Märket anger nödutgång för gående.","enText":"Marks an emergency exit for people on foot, for example in a tunnel.","tip":"","kw":["emergency exit","tunnel exit","nödutgång"],"img":"E28-1","variants":[{"key":"E28-2","en":"The same sign mirrored"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/nodutgang/","related":["E29"]},{"id":"E29","cat":"E","sv":"Utrymningsväg","en":"Escape route","svText":"Märket anger riktning och avstånd till nödutgång eller motsvarande för gående. Märket är uppsatt med högst 25 meters mellanrum.","enText":"Shows the direction and distance to an emergency exit or similar for people on foot. The signs are placed at most 25 metres apart.","tip":"","kw":["evacuation route","tunnel","emergency exit direction"],"img":"E29-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/utrymningsvag/","related":["E28"]},{"id":"E30","cat":"E","sv":"Särskilda bestämmelser för parkering","en":"Special rules for parking","svText":"Märket anger att parkering är tillåten med de infogade villkoren. Märket kan också ange avvikelse från den reglering som anges med det märke som den är uppsatt under. De närmare föreskrifterna för märke E19, parkering, utom sjätte och sjunde styckena, gäller även för detta märke. För tid gäller de närmare föreskrifterna för tilläggstavla T6, tidsangivelse. Andra villkor kan anges på märket. Märket används under något av märkena C35, förbud mot att parkera fordon, C36, förbud mot att parkera fordon på dag med udda datum, C37, förbud mot att parkera fordon på dag med jämnt datum, C38, datumparkering, C39, förbud mot att stanna och parkera fordon, C40, ändamålsplats, C42, vändplats, D10, påbjudet körfält eller körbana för fordon i linjetrafik m.fl., E19, parkering, eller E22, busshållplats.","enText":"A panel showing that parking is allowed with the conditions shown in it, for example a time limit. It can also make an exception to the sign it is placed under. Times work as on panel T6.","tip":"","kw":["parking time limit","parking conditions"],"img":"E30","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/sarskilda-bestammelser-for-parkering/","related":["E19","C45"]},{"id":"E31","cat":"E","sv":"Miljözon","en":"Environmental zone","svText":"Märket anger att bestämmelserna i 4 kap. 22-24 a §§ trafikförordningen (1998:1276) är tillämpliga. Om märket används som förberedande upplysning om att en miljözon börjar, anges avståndet på en tilläggstavla. Märket kan även vara infogat i ett lokaliseringsmärke. Märket är uppsatt vid infarterna till miljözonen och gäller till den plats där ett märke E6, tättbebyggt område upphör, märke E32, slut på miljözon eller ett annat miljözonsmärke är uppsatt.","enText":"Marks the start of an environmental zone (miljözon), where only vehicles meeting certain emission standards may be driven (Road Traffic Ordinance, chapter 4, sections 22–24 a). Class 1 covers heavy trucks and buses, class 2 covers cars, light trucks and light buses, and class 3 has the strictest rules for both groups. The zone applies until sign E6 (end of built-up area), E32 (end of zone) or another zone sign.","tip":"","kw":["low emission zone","miljözon","clean air zone"],"img":"E31-1","variants":[{"key":"E31-2","en":"Environmental zone class 2"},{"key":"E31-3","en":"Environmental zone class 3"},{"key":"E31-4","en":"Environmental zone classes 1 and 2"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/miljozon/","related":["E32"]},{"id":"E32","cat":"E","sv":"Slut på miljözon","en":"End of environmental zone","svText":"Märket anger att en miljözon slutar.","enText":"Marks the end of an environmental zone.","tip":"","kw":["end of low emission zone"],"img":"E32-1","variants":[{"key":"E32-2","en":"End of environmental zone class 2"},{"key":"E32-3","en":"End of environmental zone class 3"},{"key":"E32-4","en":"End of environmental zone classes 1 and 2"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/slut-pa-miljozon/","related":["E31"]},{"id":"E33","cat":"E","sv":"Cykelgata","en":"Cycle street","svText":"Märket anger att bestämmelserna i 8 kap. 1 a § trafikförordningen (1998:1276) är tillämpliga.","enText":"Marks a cycle street (cykelgata). Vehicles may not drive faster than 30 km/h, may only park in specially arranged parking spaces, and drivers of motor vehicles must adapt their speed to the cyclists. A driver who comes onto a cycle street from another road must give way to vehicles on the cycle street.","tip":"","kw":["bicycle street","cykelgata","cycle priority street"],"img":"E33-CYKELGATA","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/cykelgata/","related":["E34"]},{"id":"E34","cat":"E","sv":"Cykelgata upphör","en":"End of cycle street","svText":"Märket anger att en cykelgata upphör. <b>Kommentar:</b> Det förekommer för närvarande inga närmare föreskrifter om vägmärkets storlekar. Andra vägmärken som E7 Gågata och E11 Rekommenderad lägre hastighet som kan förekomma i likande trafikmiljöer har storlekarna Liten 0,4 x 0,4 m, Normal 0,6 x 0,6 m och Stor 0,8 x 0,8 m.","enText":"Marks the end of a cycle street.","tip":"","kw":["end of bicycle street"],"img":"E34-CYKELGATA-UPPHOR","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/anvisningsmarken/cykelgata-upphor/","related":["E33"]},{"id":"F1","cat":"F","sv":"Orienteringstavla","en":"Advance direction sign","svText":"Märket är en förberedande upplysning om korsning, cirkulationsplats eller motsvarande. Om det finns särskilda skäl kan upplysning om två korsningar anges på märket.","enText":"Gives advance information about a junction, roundabout or similar, showing the directions and destinations. Where there are special reasons it can show two junctions.","tip":"The colour of a direction sign tells you the type of road – blue for public roads, green for motorways and expressways, yellow with a red border for private roads.","kw":["direction sign","signpost","orienteringstavla"],"img":"F1-1","variants":[{"key":"F1-2","en":"Advance direction sign for a roundabout"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/orienteringstavla2/","related":[]},{"id":"F2","cat":"F","sv":"Orienteringstavla vid förbjuden sväng i korsning","en":"Advance direction sign for a banned turn","svText":"Märket är en förberedande upplysning om att det är förbjudet att svänga i en korsning, men att en annan körriktning kan väljas.","enText":"Gives advance information that turning is prohibited at the junction ahead, and shows another way to reach the destination.","tip":"","kw":["turn ban","detour","diversion"],"img":"F2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/orienteringstavla-vid-forbjuden-svang-i-korsning/","related":[]},{"id":"F3","cat":"F","sv":"Tabellorienteringstavla","en":"Advance direction sign in table form","svText":"Märket är en förberedande upplysning om korsning, cirkulationsplats eller motsvarande. Avståndsangivelsen på märket är anpassad till förhållandena på platsen. Samtliga färdriktningar i korsningen anges.","enText":"Gives advance information about a junction, roundabout or similar as a list, with all directions shown. The distance shown is adjusted to the place.","tip":"","kw":["direction table"],"img":"F3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/tabellorienteringstavla/","related":[]},{"id":"F4","cat":"F","sv":"Avfartsorienteringstavla","en":"Advance exit sign","svText":"Märket är en förberedande upplysning om avfart. Avståndsangivelsen på märket är anpassad till förhållandena på platsen.","enText":"Gives advance information about an exit. The distance shown is adjusted to the place.","tip":"","kw":["exit ahead","avfart"],"img":"F4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/avfartsorienteringstavla/","related":[]},{"id":"F5","cat":"F","sv":"Vägvisare","en":"Direction sign","svText":"Märket är uppsatt i anslutning till en korsning. Om avstånd anges ska det anges i hela kilometer.","enText":"Placed at a junction and points the way to a destination. Distances, if shown, are given in whole kilometres.","tip":"","kw":["signpost","vägvisare","finger post"],"img":"F5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/vagvisare/","related":[]},{"id":"F6","cat":"F","sv":"Tabellvägvisare","en":"Direction sign in table form","svText":"Märket kan användas i stället för märke F5, vägvisare, och är uppsatt på kort avstånd före en korsning, cirkulationsplats eller i utfarten från en cirkulationsplats. Används märket i anslutning till ett sjukhusområde, industriområde eller motsvarande får området anges överst på märket utan riktningsangivelse.","enText":"Can be used instead of F5. It stands a short distance before a junction or roundabout, or in the exit from a roundabout. Near a hospital, industrial area or similar, the area may be named at the top without a direction.","tip":"","kw":["direction table"],"img":"F6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/tabellvagvisare/","related":[]},{"id":"F7","cat":"F","sv":"Avfartsvisare","en":"Exit sign","svText":"Märket är uppsatt där avfarten börjar.","enText":"Placed where an exit begins.","tip":"","kw":["exit","avfart"],"img":"F7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/avfartsvisare/","related":[]},{"id":"F8","cat":"F","sv":"Körfältsvägvisare","en":"Lane direction sign (overhead)","svText":"Märket anger det eller de körfält som är lämpligt att använda för färd till målet. Märket är uppsatt över det eller de körfält det avser. Körfältsvägvisare kan även användas som förberedande upplysning om avfart. I sådana fall anges avståndet till avfarten under angivelsen för avfarten.","enText":"Shows which lane or lanes are suitable for reaching a destination. It hangs above the lane or lanes it refers to. It can also give advance notice of an exit; the distance to the exit is then shown under it.","tip":"","kw":["gantry sign","overhead sign","lane sign","körfältsvägvisare"],"img":"F8-1","variants":[{"key":"F8-2","en":"Lane direction signs that also give advance notice of an exit, with the distance"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/korfaltsvagvisare/","related":[]},{"id":"F9","cat":"F","sv":"Samlingsmärke för vägvisning","en":"Collective direction sign","svText":"Inom klammer anges mål som nås via ett gemensamt vägval och under klammerns spets anges det gemensamma vägvalet. Avståndet till aktuell avfart eller korsning kan anges på en tilläggstavla.","enText":"The destinations inside the bracket are all reached by the same choice of route, which is given under the point of the bracket. The distance to the exit or junction can be shown on a panel.","tip":"","kw":["grouped destinations"],"img":"F9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/samlingsmarke-for-vagvisning/","related":[]},{"id":"F10","cat":"F","sv":"Platsmärke","en":"Place name sign","svText":"Märket anger en ort eller annan plats av betydelse för orienteringen. Kommun-, stads- eller länsvapen kan vara infogat i märket.","enText":"Shows the name of a town or other place that helps with orientation. A municipal, town or county coat of arms may be shown.","tip":"","kw":["town name","place name","platsmärke"],"img":"F10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/platsmarke/","related":[]},{"id":"F11","cat":"F","sv":"Vägnamn","en":"Road name","svText":"Märket anger namn på en viss väg eller led. Avvikelse från färg får inte ske.","enText":"Shows the name of a road or route.","tip":"","kw":["street name","road name","vägnamn"],"img":"F11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/vagnamn/","related":[]},{"id":"F12","cat":"F","sv":"Vattendrag","en":"Watercourse","svText":"","enText":"Shows the name of a river or stream.","tip":"","kw":["river name","stream"],"img":"F12-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/vattendrag/","related":[]},{"id":"F13","cat":"F","sv":"Avståndstavla","en":"Distance sign","svText":"Avstånd anges i hela kilometer. Vägnamn eller vägnummer kan vara infogade i märket.","enText":"Shows distances to destinations in whole kilometres. A road name or road number may be shown.","tip":"","kw":["distances","km","avståndstavla"],"img":"F13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/avstandstavla/","related":[]},{"id":"F14","cat":"F","sv":"Vägnummer","en":"Road number","svText":"Vägnummer anges endast för vägar i nummergruppen 1-499. Ett märke med streckad bård anger att vägen leder till den väg som vägvisas med det nummer som anges på märket.","enText":"Shows the road number. Numbers are only given for roads numbered 1–499. A sign with a dashed border means the road leads to the road with the number shown.","tip":"Green E-numbers are European roads (for example E4). Blue numbers are national and county roads.","kw":["road number","E-road","European route","riksväg"],"img":"F14-1","variants":[{"key":"F14-2","en":"Road leading to European road E4 (dashed border)"},{"key":"F14-3","en":"National or county road number"},{"key":"F14-4","en":"Road leading to road 58 (dashed border)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/vagnummer/","related":[]},{"id":"F15","cat":"F","sv":"Omledning","en":"Permanent diversion route","svText":"Märket anger permanent omledningsväg för ordinarie numrerad väg. Avvikelse från färg får inte ske.","enText":"Shows a permanent alternative route for a numbered road.","tip":"","kw":["diversion route","omledning"],"img":"F15-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/omledning/","related":[]},{"id":"F16","cat":"F","sv":"Ökning av antal körfält","en":"More lanes ahead","svText":"Märket anger att antalet körfält ökar. Märket är anpassat efter förhållandena på platsen. Symboler för fordonsslag, vägnummer eller fysisk avgränsning mellan motriktade körfält kan vara infogade i märket. Märket används även som förberedande upplysning om att antalet körfält ökar. Avståndet anges då på en tilläggstavla. Vid tillfällig trafikomläggning får märket utföras på orange botten. I övrigt får avvikelse från färg inte ske.","enText":"Shows that the number of lanes increases. The sign is drawn to match the place, and symbols for vehicle types, road numbers or a physical barrier between opposite lanes may be added. Used in advance, the distance is shown on a panel. At temporary diversions it may have an orange background.","tip":"","kw":["extra lane","lane gain","overtaking lane"],"img":"F16-1","variants":[{"key":"F16-2","en":"More lanes ahead (another layout)"},{"key":"F16-3","en":"More lanes ahead, with a barrier between the directions"},{"key":"F16-4","en":"More lanes ahead (another layout)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/okning-av-antal-korfalt/","related":["F17"]},{"id":"F17","cat":"F","sv":"Minskning av antal körfält","en":"Fewer lanes ahead","svText":"Märket anger att antalet körfält minskar. Märket är anpassat efter förhållandena på platsen. Märket används även som förberedande upplysning om att antalet körfält minskar. Avståndet anges då på en tilläggstavla. Vid tillfällig trafikomläggning får märket utföras på orange botten. I övrigt får avvikelse från färg inte ske.","enText":"Shows that the number of lanes decreases. The sign is drawn to match the place. Used in advance, the distance is shown on a panel. At temporary diversions it may have an orange background.","tip":"On a 2+1 road this sign tells you the overtaking lane is ending. Finish overtaking in good time and merge back.","kw":["lane ends","lane drop","2+1 road"],"img":"F17-1","variants":[{"key":"F17-2","en":"Fewer lanes ahead (another layout)"},{"key":"F17-3","en":"Fewer lanes ahead (another layout)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/minskning-av-antal-korfalt/","related":["F16","E15"]},{"id":"F18","cat":"F","sv":"Körfältsindelning på sträcka","en":"Lane layout on the road ahead","svText":"Märket anger körriktning i körfält. Märket är anpassat efter förhållandena på platsen. Symboler för fordonsslag, vägnummer eller fysisk avgränsning mellan motriktade körfält kan vara infogade i märket. Märket används även som förberedande upplysning om att körfält börjar. Avståndet anges då på en tilläggstavla. Vid tillfällig trafikomläggning kan märket vara utfört med orange botten. I övrigt får avvikelse från färg inte ske.","enText":"Shows the direction of traffic in each lane. The sign is drawn to match the place, and symbols for vehicle types, road numbers or a physical barrier between opposite lanes may be added. Used in advance, the distance is shown on a panel. At temporary diversions it may have an orange background.","tip":"","kw":["lane arrangement","2+1 road"],"img":"F18-1","variants":[{"key":"F18-2","en":"Lane layout with a barrier between the directions"},{"key":"F18-3","en":"Lane layout (another layout)"},{"key":"F18-4","en":"Lane layout (another layout)"},{"key":"F18-5","en":"Lane layout with a barrier between the directions (another layout)"},{"key":"F18-6","en":"Lane layout with a barrier between the directions (another layout)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/korfaltsindelning-pa-stracka/","related":[]},{"id":"F19","cat":"F","sv":"Väganslutning med accelerationsfält","en":"Joining road with acceleration lane","svText":"Märket är anpassat efter förhållandena på platsen. Vid tillfällig trafikomläggning kan märket vara utfört med orange botten. I övrigt får avvikelse från färg inte ske.","enText":"Shows that a road joins with an acceleration lane. The sign is drawn to match the place. At temporary diversions it may have an orange background.","tip":"","kw":["slip road","merge","acceleration lane","påfart"],"img":"F19-1","variants":[{"key":"F19-2","en":"Joining road with acceleration lane (another layout)"},{"key":"F19-3","en":"Joining road with acceleration lane (another layout)"},{"key":"F19-4","en":"Joining road with acceleration lane (another layout)"},{"key":"F19-5","en":"Joining road with acceleration lane (another layout)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/vaganslutning-med-accelerationsfalt/","related":[]},{"id":"F20","cat":"F","sv":"Väganslutning med separat körfält","en":"Joining road with its own lane","svText":"Märket är anpassat efter förhållandena på platsen. Vid tillfällig trafikomläggning kan märket vara utfört med orange botten. I övrigt får avvikelse från färg inte ske.","enText":"Shows that a road joins with a separate lane of its own. The sign is drawn to match the place. At temporary diversions it may have an orange background.","tip":"","kw":["added lane","slip road"],"img":"F20-1","variants":[{"key":"F20-2","en":"Joining road with its own lane (another layout)"},{"key":"F20-3","en":"Joining road with its own lane (another layout)"},{"key":"F20-4","en":"Joining road with its own lane (another layout)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/vaganslutning-med-separat-korfalt/","related":[]},{"id":"F21","cat":"F","sv":"Körfältsindelning före korsning","en":"Lanes before a junction","svText":"Märket visar lämpligt körfält för fortsatt färd. Märket är anpassat till förhållandena på platsen. Avvikelse från färg får inte ske.","enText":"Shows the suitable lane for the onward journey before a junction. The sign is drawn to match the place.","tip":"","kw":["lane choice","junction lanes"],"img":"F21-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/korfaltsindelning-fore-korsning/","related":[]},{"id":"F22","cat":"F","sv":"Riksmärke","en":"National border sign","svText":"Märket anger gräns till Sverige eller annat EU-land. Avvikelser från färg får inte ske.","enText":"Marks the border of Sweden or another EU country.","tip":"","kw":["border","country sign","EU"],"img":"F22-2","variants":[{"key":"F22-1","en":"The border sign for Finland"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/riksmarke/","related":[]},{"id":"F23","cat":"F","sv":"Orienteringstavla för omledningsväg","en":"Diversion advance sign","svText":"Märket anger omledningsväg när ordinarie väg tillfälligt är avstängd. Avvikelse från färg får inte ske.","enText":"Shows the diversion route when the normal road is temporarily closed.","tip":"","kw":["detour","diversion","road closed"],"img":"F23-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/orienteringstavla-for-omledningsvag/","related":[]},{"id":"F24","cat":"F","sv":"Färdriktning vid omledning","en":"Diversion direction","svText":"Märket anger färdriktning vid tillfällig omledning av trafik. Avvikelse från färg får inte ske.","enText":"Shows the direction to follow during a temporary diversion of traffic.","tip":"","kw":["detour arrow","diversion"],"img":"F24-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/fardriktning-vid-omledning/","related":[]},{"id":"F25","cat":"F","sv":"Körfält upphör","en":"Lane closed – move to another lane","svText":"Märket anger att ett körfält tillfälligt är avstängt och att ett annat körfält kan användas i färdriktningen. Märket är anpassat efter förhållandena på platsen. Avvikelse från färg får inte ske.","enText":"Shows that a lane is temporarily closed and that another lane in your direction can be used. The sign is drawn to match the place.","tip":"","kw":["road works","lane closure"],"img":"F25-1","variants":[{"key":"F25-3","en":"Lane closed (another layout)"},{"key":"F25-4","en":"Lane closed (another layout)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/korfalt-upphor/","related":["F26"]},{"id":"F26","cat":"F","sv":"Körfält avstängt","en":"Lane closed – traffic in the opposite lane","svText":"Märket anger att ett körfält tillfälligt är avstängt och att inget annat körfält i färdriktningen kan användas. Märket är anpassat efter förhållandena på platsen. Avvikelse från färg får inte ske.","enText":"Shows that a lane is temporarily closed and that no other lane in your direction can be used (you share the road with oncoming traffic). The sign is drawn to match the place.","tip":"","kw":["road works","contraflow"],"img":"F26-1","variants":[{"key":"F26-2","en":"Lane closed (another layout)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/korfalt-avstangt/","related":["F25"]},{"id":"F27","cat":"F","sv":"Trafikplatsnummer","en":"Junction number","svText":"Märket anger numret på trafikplatsen. Märket kan vara kompletterat med avfartens beteckning. Avvikelse från färg får inte ske.","enText":"Shows the number of the junction (exit). It may be completed with the exit's designation.","tip":"","kw":["exit number","junction number","trafikplatsnummer"],"img":"F27-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/trafikplatsnummer/","related":[]},{"id":"F28","cat":"F","sv":"Parkeringshus","en":"Multi-storey car park","svText":"Upplysning om att parkeringsplatsen är fullbelagd eller om att det finns lediga platser kan lämnas i anslutning till märket. Parkeringshusets namn kan vara infogat i märket.","enText":"Marks a parking garage. Information about whether it is full or has free spaces may be given next to it, and its name may be shown.","tip":"","kw":["parking garage","car park","parkeringshus"],"img":"F28-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/parkeringshus/","related":[]},{"id":"F29","cat":"F","sv":"Infartsparkering","en":"Park and ride","svText":"Märket anger parkeringsplats i anslutning till kollektivtrafik. Symbolen på märket anger vilken typ av kollektivtrafik som är tillgänglig. Transportstyrelsen får meddela föreskrifter om vilka andra symboler som får användas. Parkeringsplatsens namn kan vara infogat i märket. Avvikelse från färg får inte ske.","enText":"Marks a car park connected to public transport. The symbol shows the type of public transport available. The car park's name may be shown.","tip":"","kw":["park and ride","infartsparkering","commuter parking"],"img":"F29-1","variants":[{"key":"F29-2","en":"Park and ride with a bus"},{"key":"F29-3","en":"Park and ride (another type of public transport)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/infartsparkering/","related":[]},{"id":"F30","cat":"F","sv":"Lokal slinga","en":"Local loop","svText":"Märket anger ringväg eller motsvarande. Märket kan vara kompletterat med beteckning eller motsvarande. Avvikelse från färg får inte ske.","enText":"Marks a ring road or similar route. It can carry a designation.","tip":"","kw":["ring road","loop"],"img":"F30-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/lokal-slinga/","related":[]},{"id":"F31","cat":"F","sv":"Lämplig väg eller förbifart för visst fordonsslag eller trafikantgrupp","en":"Suitable route for a vehicle type or road user group","svText":"Fordonsslaget eller trafikantgruppen anges med symbol enligt 28 §.","enText":"Shows a suitable road or bypass for the vehicle type or road user group shown by the symbol.","tip":"","kw":["truck route","bypass"],"img":"F31-1","variants":[{"key":"F31-2","en":"The same sign for another vehicle type or user group"},{"key":"F31-3","en":"The same sign for another vehicle type or user group"},{"key":"F31-4","en":"The same sign for another vehicle type or user group"},{"key":"F31-5","en":"The same sign for another vehicle type or user group"},{"key":"F31-6","en":"The same sign for another vehicle type or user group"},{"key":"F31-7","en":"The same sign for another vehicle type or user group"},{"key":"F31-8","en":"The same sign for another vehicle type or user group"},{"key":"F31-9","en":"The same sign for another vehicle type or user group"},{"key":"F31-10","en":"The same sign for another vehicle type or user group"},{"key":"F31-11","en":"The same sign for another vehicle type or user group"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/lamplig-vag-eller-forbifart-for-visst-fordonsslag-eller-trafikantgrupp/","related":[]},{"id":"F31a","cat":"F","sv":"Färdväg för långa fordonståg","en":"Route for long vehicle combinations","svText":"Märket anger färdväg för långa fordonståg enligt föreskrifter meddelade med stöd av 4 kap. 17 f § trafikförordningen (1998:1276). Avvikelse från färg får inte ske.","enText":"Shows the route for long vehicle combinations (up to 34.5 metres) under the special rules for such roads.","tip":"","kw":["long trucks","34.5 m"],"img":"F31A","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/fardvag-for-langa-fordonstag/","related":[]},{"id":"F32","cat":"F","sv":"Farligt gods","en":"Dangerous goods route","svText":"Märket anger rekommenderad färdväg för fordon med last som omfattas av krav på märkning med orangefärgad skylt enligt föreskrifter som har meddelats med stöd av lagen (2006:263) om transport av farligt gods. Avvikelse från färg får inte ske.","enText":"Shows the recommended route for vehicles carrying dangerous goods (marked with orange plates).","tip":"","kw":["ADR route","hazardous goods"],"img":"F32-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/farligt-gods/","related":["C9","D12"]},{"id":"F33","cat":"F","sv":"Räddningsplats","en":"Rescue point","svText":"Märket anger en räddningsplats vid vägarbeten eller motsvarande. Siffran anger räddningsplatsens nummer. Avvikelse från färg får inte ske.","enText":"Marks a rescue point at road works or similar. The number is the rescue point's number.","tip":"","kw":["rescue point","R1"],"img":"F33-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-vagvisning/raddningsplats/","related":[]},{"id":"F34","cat":"F","gc":true,"sv":"Vägvisare","en":"Direction sign for pedestrians and cyclists","svText":"Märket anger väg till en ort, plats, anläggning eller liknande. Avstånd i kilometer kan anges. Andra symboler kan förekomma på märket. Transportstyrelsen får meddela föreskrifter om vilka symboler som får förekomma. Transportstyrelsen får också meddela föreskrifter om att det inte behöver förekomma någon symbol på märket.","enText":"Points the way to a town, place or facility for people walking or cycling. Distance in kilometres may be shown.","tip":"","kw":["cycle signpost"],"img":"F34-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-gang-och-cykeltrafik/vagvisare/","related":[]},{"id":"F35","cat":"F","gc":true,"sv":"Tabellvägvisare","en":"Direction table for pedestrians and cyclists","svText":"Märket anger väg till orter, platser, anläggningar eller liknande. Avståndet anges i kilometer. Andra symboler kan förekomma på märket. Transportstyrelsen får meddela föreskrifter om vilka symboler som får förekomma. Transportstyrelsen får också meddela föreskrifter om att det inte behöver förekomma någon symbol på märket.","enText":"Points the way to several towns, places or facilities, with distances in kilometres, for people walking or cycling.","tip":"","kw":["cycle route sign"],"img":"F35-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-gang-och-cykeltrafik/tabellvagvisare/","related":[]},{"id":"F36","cat":"F","gc":true,"sv":"Platsmärke","en":"Place name sign for pedestrians and cyclists","svText":"Märket anger en ort eller annan plats av betydelse för orienteringen. Kommun-, stads- eller länsvapen kan vara infogat i märket.","enText":"Shows the name of a town or other place on a walking or cycling route. A coat of arms may be shown.","tip":"","kw":["place name"],"img":"F36-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-gang-och-cykeltrafik/platsmarke/","related":[]},{"id":"F37","cat":"F","gc":true,"sv":"Avståndstavla","en":"Distance sign for pedestrians and cyclists","svText":"Märket anger avståndet till angivna orter, platser, anläggningar eller liknande. Avståndet anges i kilometer. Andra symboler kan förekomma på märket. Transportstyrelsen får meddela föreskrifter om vilka symboler som får förekomma. Transportstyrelsen får också meddela föreskrifter om att det inte behöver förekomma någon symbol på märket.","enText":"Shows the distance in kilometres to places on a walking or cycling route.","tip":"","kw":["cycle distance"],"img":"F37-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-gang-och-cykeltrafik/avstandstavla/","related":[]},{"id":"F38","cat":"F","gc":true,"sv":"Cykelled","en":"Cycle route","svText":"Märket anger en särskilt anordnad cykelled. Märkets färgsättning kan variera.","enText":"Marks a specially arranged cycle route. The colours of the sign can vary.","tip":"","kw":["cycle route","bike route","cykelled"],"img":"F38-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-gang-och-cykeltrafik/cykelled/","related":[]},{"id":"G1","cat":"G","sv":"Post","en":"Post office","svText":"Märket anger postombud där brev och pakethantering samt frimärksförsäljning erbjuds.","enText":"Marks a postal agent offering letter and parcel services and stamps.","tip":"","kw":["post","mail","parcels"],"img":"G1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/post/","related":[]},{"id":"G2","cat":"G","sv":"Hjälptelefon","en":"Emergency telephone","svText":"","enText":"Marks an emergency telephone.","tip":"","kw":["SOS phone","help phone","hjälptelefon"],"img":"G2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/hjalptelefon/","related":[]},{"id":"G3","cat":"G","sv":"Radiostation för vägtrafikinformation","en":"Traffic information radio","svText":"Märket anger att vägtrafikinformation ges regelbundet i återkommande sändningar som är avsedda att täcka ett större område.","enText":"Shows a radio station that regularly broadcasts road traffic information covering a larger area, with its frequency.","tip":"","kw":["radio","traffic news","FM"],"img":"G3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/radiostation-for-vagtrafikinformation/","related":[]},{"id":"G4","cat":"G","sv":"Akutsjukhus","en":"Hospital with emergency department","svText":"Märket anger ett sjukhus med akutmottagning.","enText":"Marks a hospital with an emergency department (akutmottagning).","tip":"","kw":["hospital","emergency","A&E","akutsjukhus"],"img":"G4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/akutsjukhus/","related":[]},{"id":"G5","cat":"G","sv":"Industriområde","en":"Industrial area","svText":"Märket anger ett område för industri eller annan liknande verksamhet.","enText":"Marks an area for industry or similar business.","tip":"","kw":["industry","factories"],"img":"G5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/industriomrade/","related":[]},{"id":"G6","cat":"G","sv":"Järnvägsstation","en":"Railway station","svText":"","enText":"Marks a railway station.","tip":"","kw":["train station"],"img":"G6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/jarnvagsstation/","related":[]},{"id":"G7","cat":"G","sv":"Busstation","en":"Bus station","svText":"Märket anger en busstation som utgör knutpunkt för flera busslinjer.","enText":"Marks a bus station where several bus lines meet.","tip":"","kw":["bus terminal"],"img":"G7","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/busstation/","related":[]},{"id":"G8","cat":"G","sv":"Flygplats","en":"Airport","svText":"Märket anger en flygplats med reguljär flygtrafik.","enText":"Marks an airport with scheduled flights.","tip":"","kw":["airport","flights"],"img":"G8-1","variants":[{"key":"G8-2","en":"The aircraft symbol drawn in another direction"},{"key":"G8-3","en":"The aircraft symbol drawn in another direction"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/flygplats/","related":[]},{"id":"G9","cat":"G","sv":"Brandsläckare","en":"Fire extinguisher","svText":"","enText":"Marks a fire extinguisher, for example in a tunnel.","tip":"","kw":["fire extinguisher"],"img":"G9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/brandslackare/","related":[]},{"id":"G10","cat":"G","sv":"Handelsområde","en":"Shopping area","svText":"Märket anger ett område för handel.","enText":"Marks an area for shopping.","tip":"","kw":["shops","retail park"],"img":"G10","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/handelsomrade/","related":[]},{"id":"G11","cat":"G","sv":"Färja","en":"Ferry","svText":"Märket anger ett färjeläge eller att angivet färdmål nås med färja.","enText":"Marks a ferry terminal, or shows that the destination is reached by ferry.","tip":"","kw":["car ferry","färja"],"img":"G11","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/farja/","related":[]},{"id":"G12","cat":"G","sv":"Personfärja","en":"Passenger ferry","svText":"Märket anger ett färjeläge för personfärja eller att angivet färdmål endast kan nås med färja avsedd för persontransport.","enText":"Marks a terminal for a passenger ferry, or shows that the destination can only be reached by a ferry for passengers.","tip":"","kw":["foot ferry","passenger boat"],"img":"G12","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-allmanna-inrattningar-med-mera/personfarja/","related":[]},{"id":"H1","cat":"H","sv":"Informationsplats","en":"Information point","svText":"Märket anger en plats där det går att få information. Uppgift om vilken typ av information som finns kan anges i anslutning till märket.","enText":"Marks a place where you can get information. The type of information may be shown next to the sign.","tip":"","kw":["tourist information","i"],"img":"H1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/informationsplats/","related":[]},{"id":"H2","cat":"H","sv":"Fordonsverkstad","en":"Vehicle repair workshop","svText":"","enText":"Marks a vehicle repair workshop.","tip":"","kw":["garage","mechanic","verkstad"],"img":"H2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/fordonsverkstad/","related":[]},{"id":"H3","cat":"H","sv":"Drivmedel","en":"Fuel","svText":"Märket anger en anläggning som tillhandahåller drivmedel. Företagsemblem kan anges i anslutning till märket.","enText":"Marks a place that sells fuel. A company emblem may be shown next to it.","tip":"","kw":["petrol station","gas station","filling station","drivmedel"],"img":"H3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/drivmedel/","related":[]},{"id":"H4","cat":"H","sv":"Gas för fordonsdrift","en":"Gas for vehicles","svText":"Märket anger anläggningar som tillhandahåller olika typer av fordonsgas där typ av gas framgår av förkortningen i märket. Förkortningen CNG anger komprimerad naturgas. Transportstyrelsen får meddela föreskrifter om vilka andra förkortningar som får förekomma och vad de anger.","enText":"Marks places that sell different kinds of vehicle gas. The abbreviation shows the type; CNG means compressed natural gas.","tip":"","kw":["CNG","LPG","LNG","hydrogen","biogas"],"img":"H4-1","variants":[{"key":"H4-2","en":"LPG – liquefied petroleum gas"},{"key":"H4-3","en":"LNG – liquefied natural gas"},{"key":"H4-4","en":"H2 – hydrogen"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/gas-for-fordonsdrift/","related":[]},{"id":"H5","cat":"H","sv":"Servering","en":"Café","svText":"Märket anger en anläggning som serverar drycker och enklare maträtter.","enText":"Marks a place serving drinks and simple meals.","tip":"","kw":["snacks","coffee","servering"],"img":"H5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/servering/","related":[]},{"id":"H6","cat":"H","sv":"Restaurang","en":"Restaurant","svText":"","enText":"Marks a restaurant.","tip":"","kw":["food","dining"],"img":"H6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/restaurang/","related":[]},{"id":"H7","cat":"H","sv":"Hotell","en":"Hotel","svText":"","enText":"Marks a hotel.","tip":"","kw":["accommodation"],"img":"H7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/hotell/","related":[]},{"id":"H8","cat":"H","sv":"Vandrarhem","en":"Hostel","svText":"","enText":"Marks a hostel (vandrarhem).","tip":"","kw":["youth hostel"],"img":"H8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/vandrarhem/","related":[]},{"id":"H9","cat":"H","sv":"Stugby","en":"Holiday cabin village","svText":"Märket anger en anläggning med ett större antal stugor.","enText":"Marks a place with a larger number of cabins.","tip":"","kw":["cabins","stugby"],"img":"H9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/stugby/","related":[]},{"id":"H10","cat":"H","sv":"Stuga","en":"Holiday cabins","svText":"Märket anger en anläggning med ett fåtal stugor.","enText":"Marks a place with a few cabins.","tip":"","kw":["cabin","stuga"],"img":"H10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/stuga/","related":[]},{"id":"H11","cat":"H","sv":"Campingplats","en":"Campsite","svText":"Märket anger en anläggning som tillhandahåller platser för såväl tält som fordon med bostadsutrymme.","enText":"Marks a site with places for both tents and vehicles with living accommodation (caravans and motorhomes).","tip":"","kw":["camping","tents"],"img":"H11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/campingplats/","related":[]},{"id":"H12","cat":"H","sv":"Husvagnsplats","en":"Caravan site","svText":"Märket anger en anläggning som enbart tillhandahåller platser för fordon med bostadsutrymme.","enText":"Marks a site with places only for vehicles with living accommodation.","tip":"","kw":["caravans","motorhomes"],"img":"H12-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/husvagnsplats/","related":[]},{"id":"H13","cat":"H","sv":"Rastplats","en":"Rest area","svText":"Märket anger en rastplats där det finns toalett som är tillgänglig även för rörelsehindrade.","enText":"Marks a rest area with a toilet that can also be used by people with reduced mobility.","tip":"","kw":["lay-by","rastplats","picnic"],"img":"H13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/rastplats/","related":[]},{"id":"H14","cat":"H","sv":"Toalett","en":"Toilet","svText":"Märket anger en toalett som är tillgänglig även för rörelsehindrade.","enText":"Marks a toilet that can also be used by people with reduced mobility.","tip":"","kw":["WC","restroom"],"img":"H14-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/toalett/","related":[]},{"id":"H15","cat":"H","sv":"Badplats","en":"Bathing place","svText":"Märket anger en badstrand eller annan badanläggning.","enText":"Marks a beach or other bathing facility.","tip":"","kw":["beach","swimming"],"img":"H15-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/badplats/","related":[]},{"id":"H16","cat":"H","sv":"Friluftsområde","en":"Outdoor recreation area","svText":"","enText":"Marks an outdoor recreation area.","tip":"","kw":["nature","park"],"img":"H16-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/friluftsomrade/","related":[]},{"id":"H17","cat":"H","sv":"Vandringsled","en":"Hiking trail","svText":"","enText":"Marks a hiking trail.","tip":"","kw":["walking trail"],"img":"H17-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/vandringsled/","related":[]},{"id":"H18","cat":"H","sv":"Stollift","en":"Chair lift","svText":"Märket anger en liftanläggning med stolar eller liknande.","enText":"Marks a lift with chairs or similar.","tip":"","kw":["ski lift"],"img":"H18-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/stollift/","related":[]},{"id":"H19","cat":"H","sv":"Släplift","en":"Ski tow","svText":"Märket anger en liftanläggning där skidåkare dras fram.","enText":"Marks a lift where skiers are pulled along.","tip":"","kw":["drag lift","T-bar"],"img":"H19-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/slaplift/","related":[]},{"id":"H20","cat":"H","sv":"Golfbana","en":"Golf course","svText":"","enText":"Marks a golf course.","tip":"","kw":["golf"],"img":"H20-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/golfbana/","related":[]},{"id":"H21","cat":"H","sv":"Försäljningsställe för fiskekort","en":"Fishing licences sold here","svText":"","enText":"Marks a place that sells fishing licences.","tip":"","kw":["fishing permit","fiskekort"],"img":"H21-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/forsaljningsstalle-for-fiskekort/","related":[]},{"id":"H22","cat":"H","sv":"Sevärdhet","en":"Place of interest","svText":"Märket anger en sevärdhet av nationellt intresse. Sevärdhetens art anges i anslutning till märket.","enText":"Marks a sight of national interest. The kind of sight is shown next to the sign.","tip":"","kw":["sight","attraction","sevärdhet"],"img":"H22-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/sevardhet/","related":[]},{"id":"H23","cat":"H","sv":"Förberedande upplysning om vägnära service","en":"Services ahead","svText":"Märket anger vägnära serviceanläggningar samt i vissa fall namn på dessa. Symbol för serviceanläggningarna drivmedel, restaurang och hotell kan vara kompletterade med företagsemblem eller företagsnamn. På märket anges avståndet till aktuell avfart eller korsning.","enText":"Gives advance information about services near the road, sometimes with their names, and the distance to the exit or junction. Fuel, restaurant and hotel symbols may be completed with company names or emblems.","tip":"","kw":["motorway services","roadside services"],"img":"H23","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/forberedande-upplysning-om-vagnara-service/","related":[]},{"id":"H24","cat":"H","sv":"Rum och frukost","en":"Bed and breakfast","svText":"Märket anger en anläggning som tillhandahåller rum för övernattning och frukost.","enText":"Marks a place offering rooms for the night and breakfast.","tip":"","kw":["B&B"],"img":"H24-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/rum-och-frukost/","related":[]},{"id":"H25","cat":"H","sv":"Gårdsbutik","en":"Farm shop","svText":"Märket anger en anläggning med försäljning av lokalt tillverkade eller närodlade produkter.","enText":"Marks a shop selling locally made or locally grown products.","tip":"","kw":["farm shop","gårdsbutik"],"img":"H25","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/gardsbutik/","related":[]},{"id":"H26","cat":"H","sv":"Hantverk","en":"Crafts","svText":"Märket anger en anläggning med tillverkning och försäljning av hantverksprodukter.","enText":"Marks a place where handicrafts are made and sold.","tip":"","kw":["handicraft"],"img":"H26","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/hantverk/","related":[]},{"id":"H27","cat":"H","sv":"Laddstation","en":"Charging station","svText":"Märket anger en anläggning för extern laddning med elektrisk energi för fordons framdrivning.","enText":"Marks a place for charging electric vehicles.","tip":"","kw":["EV charging","laddstation","electric car"],"img":"H27","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/laddstation/","related":[]},{"id":"H28","cat":"H","sv":"Anläggning som tillhandahåller platser för bilar med bostadsutrymme","en":"Motorhome site","svText":"Märket anger en anläggning som enbart tillhandahåller platser för bilar med bostadsutrymme.","enText":"Marks a site with places only for cars with living accommodation (motorhomes).","tip":"","kw":["motorhome","camper van","husbil"],"img":"H28","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-upplysning-om-serviceanlaggningar-med-mera/anlaggning-tillhandahaller-plats-for-bil-med-bostadsutrymme/","related":[]},{"id":"I1","cat":"I","sv":"Turistväg","en":"Tourist route","svText":"Märket anger en väg eller vägsträckning av turistiskt intresse. Märket kan vara infogat i ett lokaliseringsmärke för vägvisning.","enText":"Marks a road or route of tourist interest. It can be part of a direction sign.","tip":"","kw":["scenic route","turistväg","brown sign"],"img":"I1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-turistiskt-intressanta-mal-med-mera/turistvag/","related":[]},{"id":"I2","cat":"I","sv":"Turistområde","en":"Tourist area","svText":"Symbolen på märket är anpassad till temat för turistområdet. Symbolen kan vara infogad i ett lokaliseringsmärke för vägvisning. Transportstyrelsen får meddela föreskrifter om vilka symboler som får användas.","enText":"Marks a tourist area. The symbol matches the area's theme.","tip":"","kw":["tourist region","brown sign"],"img":"I2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-turistiskt-intressanta-mal-med-mera/turistomrade/","related":[]},{"id":"I3","cat":"I","sv":"Landmärke","en":"Landmark","svText":"Märket upplyser om ett landmärke av turistiskt intresse som kan ses från vägen. Symbolen på märket visar en siluett av platsen. Transportstyrelsen får meddela föreskrifter om vilka symboler som får användas.","enText":"Tells you about a landmark of tourist interest that can be seen from the road. The symbol is a silhouette of the place.","tip":"","kw":["landmark","view"],"img":"I3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-turistiskt-intressanta-mal-med-mera/landmarke/","related":[]},{"id":"I4","cat":"I","sv":"Världsarv","en":"World Heritage Site","svText":"Märket anger ett av UNESCO beslutat världsarv. Märket kan vara infogat i ett lokaliseringsmärke för vägvisning.","enText":"Marks a World Heritage Site decided by UNESCO.","tip":"","kw":["UNESCO","world heritage","världsarv"],"img":"I4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/lokaliseringsmarken-for-turistiskt-intressanta-mal-med-mera/varldsarv/","related":[]},{"id":"J2","cat":"J","sv":"Upplysningsmärke","en":"Information sign","svText":"Märket ger upplysning av väsentligt intresse för framkomlighet eller säkerhet som inte kan ges på annat sätt. Varnings- eller förbudsmärke och lokaliseringsmärkena F14, vägnummer, och F15, omledning, kan vara infogade som förberedande upplysning. Upplysning med versal och gemen text kan förekomma.","enText":"Gives information that matters for traffic flow or safety and that cannot be given in another way – for example that road salting ends. Warning or prohibitory signs and road numbers can be shown in it as advance information.","tip":"","kw":["yellow information sign","notice","vägsaltning upphör"],"img":"J2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/upplysningsmarken/upplysningsmarke/","related":[]},{"id":"J3","cat":"J","sv":"Livsfarlig ledning","en":"Dangerous overhead power line","svText":"Märket anger att det finns en elektrisk ledning över vägen eller leden som kan innebära fara.","enText":"Warns that there is an electric line over the road or route that can be dangerous (livsfarlig ledning means \"deadly line\").","tip":"","kw":["power line","high voltage","electricity","livsfarlig ledning"],"img":"J3-1","variants":[{"key":"J3-2","en":"A smaller version of the same sign"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/upplysningsmarken/livsfarlig-ledning/","related":[]},{"id":"M1","cat":"M","sv":"Mittlinje eller körfältslinje","en":"Centre line or lane line","svText":"Mittlinje anger gränsen mellan körfält avsedda för färd i motsatta färdriktningar. Körfältslinje anger gränsen mellan körfält för färd i samma riktning. Markeringen har längdförhållandet 1:3 eller 1:1 mellan dellinje och mellanrum. Mittlinje kan även ange en cykelbanas mitt och har då längdförhållandet 1:1 mellan dellinje och mellanrum.","enText":"A broken line. As a centre line it marks the border between lanes for traffic in opposite directions; as a lane line it marks the border between lanes in the same direction. The dashes and gaps have the length ratio 1:3 or 1:1. A centre line can also mark the middle of a cycle track (ratio 1:1).","tip":"You may cross a broken centre line, for example to overtake, if it is safe.","kw":["broken line","dashed line","centre line","lane marking","mittlinje"],"img":"M1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/mittlinje-eller-korfaltslinje/","related":["M3","M8"]},{"id":"M2","cat":"M","sv":"Kantlinje","en":"Edge line","svText":"Markeringen anger en körbanas yttre gräns. Markeringen har längdförhållandet 1:2 mellan dellinje och mellanrum.","enText":"A broken line marking the outer edge of the carriageway. Ratio 1:2 between dash and gap.","tip":"","kw":["edge marking","kantlinje","road edge"],"img":"M2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/kantlinje/","related":["M8"]},{"id":"M3","cat":"M","sv":"Varningslinje","en":"Warning line","svText":"Varningslinje används för att informera om att linjen är olämplig att överskrida på grund av trafikförhållandena. Markeringen anger gränsen mellan körfält avsedda för färd i motsatta färdriktningar. Markeringen kan även användas för att upplysa om en kommande heldragen linje. Markeringen har längdförhållandet 3:1 mellan dellinje och mellanrum.","enText":"A broken line with long dashes and short gaps (ratio 3:1) between lanes for opposite directions. It tells you that crossing it is unsuitable because of traffic conditions, for example poor sight ahead. It can also warn of a solid line coming up.","tip":"Crossing a warning line is not forbidden, but it is a strong hint not to overtake here.","kw":["warning line","long dashes","varningslinje"],"img":"M3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/varningslinje/","related":["M1","M8"]},{"id":"M4","cat":"M","sv":"Ledlinje","en":"Guide line","svText":"Markeringen anger lämplig färdväg för trafik i komplicerade korsningar. Markeringen används även i andra fall där det finns behov av ledning. Markeringen har längdförhållandet 1:1 mellan dellinje och mellanrum.","enText":"A broken line (ratio 1:1) showing a suitable path through complicated junctions, or elsewhere where guidance is needed.","tip":"","kw":["guidance line","junction line","ledlinje"],"img":"M4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/ledlinje/","related":[]},{"id":"M5","cat":"M","sv":"Cykelfältslinje","en":"Cycle lane line","svText":"Markeringen anger gränsen mellan ett cykelfält och ett annat körfält. Markeringen har längdförhållandet 1:1 mellan dellinje och mellanrum.","enText":"A broken line (ratio 1:1) marking the border between a cycle lane and another lane.","tip":"","kw":["bike lane line","cykelfält"],"img":"M5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/cykelfaltslinje/","related":[]},{"id":"M6","cat":"M","sv":"Linje för fordon i linjetrafik med flera","en":"Bus lane line","svText":"","enText":"A broken line (ratio 1:1) marking the border between a lane for buses in scheduled service (and others allowed) and another lane.","tip":"","kw":["bus lane marking"],"img":"M6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/linje-for-fordon-i-linjetrafik-med-flera/","related":[]},{"id":"M7","cat":"M","sv":"Reversibelt körfält","en":"Reversible lane line","svText":"Markeringen avgränsar körfält som upplåts för trafik omväxlande i den ena och i den andra färdriktningen. Markeringen har längdförhållandet 1:1 mellan dellinje och mellanrum.","enText":"A double broken line (ratio 1:1) marking a lane that is used by traffic in one direction at some times and the other direction at other times.","tip":"","kw":["tidal flow","reversible lane"],"img":"M7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/reversibelt-korfalt/","related":[]},{"id":"M8","cat":"M","sv":"Heldragen linje","en":"Solid line","svText":"Markeringen anger att bestämmelserna i 3 kap. 11 § eller 12 § tredje stycket trafikförordningen (1998:1276) eller föreskrifter meddelade med stöd av den förordningen är tillämpliga. Heldragen linje kan vara heldragen mittlinje, heldragen körfältslinje eller heldragen kantlinje. Heldragen körfältslinje och heldragen kantlinje är enkel. Heldragen mittlinje kan vara såväl enkel som dubbel.","enText":"A solid line replaces a broken line where it is not allowed, for safety reasons, to cross over to oncoming lanes, change lanes or drive out onto the shoulder. You may not drive with any wheel over a solid line (with a few exceptions, for example to pass an obstacle or to reach a property, with special care). A solid centre line can be single or double; a solid lane line and a solid edge line are single.","tip":"A broken line running right next to a solid line on your side means you may cross from your side.","kw":["continuous line","unbroken line","heldragen linje","no crossing"],"img":"M8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/heldragen-linje/","related":["M10","M11"]},{"id":"M9","cat":"M","sv":"Spärrområde","en":"Restricted area (hatched area)","svText":"Markeringen anger ett område där fordon inte får föras enligt 3 kap. 11 § trafikförordningen. Markeringen består av vinklade eller snedställda streck beroende på förhållandena på platsen. Del av eller hela området kan utföras i vitt.","enText":"An area marked with angled or diagonal stripes and bordered by a solid line. Vehicles may not drive on it (Road Traffic Ordinance chapter 3, section 11). Part or all of the area can be painted white.","tip":"","kw":["hatched area","chevrons","spärrområde"],"img":"M9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/sparromrade/","related":[]},{"id":"M10","cat":"M","sv":"Mittlinje eller körfältslinje och heldragen linje","en":"Centre or lane line combined with a solid line","svText":"Markeringen används där det inte är tillåtet för fordon som befinner sig på samma sida som den heldragna linjen att byta körfält.","enText":"Used where vehicles on the side of the solid line may not change lanes or cross, while vehicles on the side of the broken line may.","tip":"","kw":["double line","one side solid"],"img":"M10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/mittlinje-eller-korfaltslinje-och-heldragen-linje/","related":["M8","M11"]},{"id":"M11","cat":"M","sv":"Varningslinje och heldragen linje","en":"Warning line combined with a solid line","svText":"Markeringen används där det inte är tillåtet för fordon som befinner sig på samma sida som den heldragna linjen att byta körfält.","enText":"Used where vehicles on the side of the solid line may not change lanes or cross, while vehicles on the warning-line side may (if it is safe).","tip":"","kw":["double line"],"img":"M11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/varningslinje-och-heldragen-linje/","related":["M10","M3"]},{"id":"M12","cat":"M","sv":"Mittlinje och varningslinje","en":"Centre line combined with a warning line","svText":"Markeringen används där det är olämpligt att överskrida varningslinjen på grund av trafikförhållandena.","enText":"Used where crossing the warning line is unsuitable because of the traffic conditions, while crossing from the centre-line side is less of a problem.","tip":"","kw":["double broken line"],"img":"M12-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/mittlinje-och-varningslinje/","related":["M3"]},{"id":"M13","cat":"M","sv":"Stopplinje","en":"Stop line","svText":"Markeringen anger var ett fordon ska stannas enligt ett vägmärke, en trafiksignal eller Y1, ljussignal.","enText":"Marks where a vehicle must stop because of a sign, a traffic signal or a level-crossing light signal (Y1).","tip":"","kw":["stop line","wide line across the road","stopplinje"],"img":"M13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/stopplinje/","related":["B2","M14"]},{"id":"M14","cat":"M","sv":"Väjningslinje","en":"Give-way line","svText":"Markeringen anger den linje som fordon inte bör passera när föraren iakttar väjningsplikt.","enText":"A row of triangles across the road (\"shark's teeth\") that marks the line vehicles should not pass when giving way.","tip":"","kw":["shark teeth","give way line","väjningslinje","triangles"],"img":"M14-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/vajningslinje/","related":["B1","M13"]},{"id":"M15","cat":"M","sv":"Övergångsställe","en":"Pedestrian crossing marking","svText":"Markeringen anger ett övergångsställe och är utförd där märke B3, övergångsställe, är uppsatt.","enText":"Stripes across the road marking a pedestrian crossing. It is used where sign B3 is placed.","tip":"","kw":["zebra stripes","crosswalk"],"img":"M15-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/overgangsstalle/","related":["B3"]},{"id":"M16","cat":"M","sv":"Cykelpassage eller cykelöverfart","en":"Cycle passage or cycle crossing marking","svText":"Markeringen anger en cykelpassage eller en cykelöverfart där märke B8, cykelöverfart, är uppsatt. Om markeringen avser en cykelöverfart ska den kombineras med markeringen M14, väjningslinje. Markeringen M15, övergångsställe, får utgöra en av begränsningslinjerna till en cykelpassage eller en cykelöverfart.","enText":"Marks a cycle passage or a cycle crossing (where sign B8 stands). At a cycle crossing it is combined with a give-way line (M14). A pedestrian crossing marking may form one of its edges.","tip":"With shark's teeth and sign B8 it is a cycle crossing, where you must give way. Without them it is a cycle passage, where you adapt your speed so cyclists are not put in danger.","kw":["bike crossing marking","cycle passage"],"img":"M16-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/cykelpassage-eller-cykeloverfart/","related":["B8"]},{"id":"M17","cat":"M","sv":"Farthinder","en":"Speed bump marking","svText":"Markeringen anger ett farthinder i form av gupp, grop eller liknande.","enText":"Marks a speed bump, dip or similar.","tip":"","kw":["speed hump marking"],"img":"M17-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/farthinder/","related":["A9"]},{"id":"M17a","cat":"M","sv":"Cykelbox","en":"Cycle box","svText":"Markeringen anger lämplig placering för cyklande och förare av moped klass II. Markeringen får anpassas efter förhållandena på platsen.","enText":"Marks a suitable waiting position for cyclists and class II moped riders, for example in front of cars at traffic lights. It is adapted to the place.","tip":"","kw":["advanced stop box","bike box","cykelbox"],"img":"M17A-CYKELBOX","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/cykelbox/","related":[]},{"id":"M18","cat":"M","sv":"Förberedande upplysning om väjningsplikt eller stopplikt","en":"Give-way or stop ahead","svText":"Markeringen anger att väjningsplikt eller stopplikt gäller längre fram i färdriktningen.","enText":"A triangle painted on the road warning that you will have to give way or stop further ahead.","tip":"","kw":["triangle on road","give way ahead"],"img":"M18-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/forberedande-upplysning-om-vajningsplikt-eller-stopplikt/","related":["B1","B2"]},{"id":"M19","cat":"M","sv":"Körfältspilar","en":"Lane arrows","svText":"Markeringen upplyser, för närmaste korsning, lämpligt körfält för fortsatt färd. Är körfältet avgränsat med heldragen körfältslinje ska förare följa den eller de riktningar som pilen visar. Detta gäller dock inte förare som i anslutning till korsningen färdas in i eller från ett reserverat körfält. Körfältspil med två pilangivelser i samma riktning upplyser om lämpligt körfält för fortsatt färd i närmaste och därpå följande korsning. Markeringarna upplyser också om att fordon inte får föras i motsatt riktning.","enText":"Show the suitable lane for the next junction. If the lane is bordered by solid lane lines, drivers must follow the direction or directions of the arrows (except when entering or leaving a reserved lane near the junction). Double arrows in the same direction show the lane for the next junction and the one after. The arrows also mean you may not drive in the opposite direction.","tip":"","kw":["arrows on road","turn lane","körfältspilar"],"img":"M19-1","variants":[{"key":"M19A","en":"Lane arrows before a roundabout"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/korfaltspilar/","related":[]},{"id":"M20","cat":"M","sv":"Körfältsbyte","en":"Change lanes","svText":"Markeringen anger att körfältsbyte snarast måste ske.","enText":"An arrow showing that you must change lane as soon as possible, because your lane ends.","tip":"","kw":["lane ends arrow","merge arrow"],"img":"M20-1","variants":[{"key":"M20A","en":"Advance notice of a solid centre line or a physical barrier ahead"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/korfaltsbyte/","related":[]},{"id":"M21","cat":"M","sv":"Förbud mot att stanna och parkera","en":"No stopping or parking (yellow line)","svText":"Markeringen upplyser om förbud mot att stanna och parkera fordon och är placerad i körbanans kant. Avvikelse från färg får inte ske.","enText":"A solid yellow line at the edge of the carriageway showing that stopping and parking are prohibited.","tip":"","kw":["yellow line","kerb marking","no stopping"],"img":"M21-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/forbud-mot-att-stanna-och-parkera/","related":["C39","M22"]},{"id":"M22","cat":"M","sv":"Förbud mot att parkera","en":"No parking (yellow broken line)","svText":"Markeringen upplyser om förbud mot att parkera fordon och är placerad i körbanans kant. Markeringen upplyser även om utsträckning av busshållplats. Markeringen har längdförhållandet 1:1 mellan dellinje och mellanrum. Avvikelse från färg får inte ske.","enText":"A broken yellow line at the edge of the carriageway showing that parking is prohibited. It is also used to show the extent of a bus stop.","tip":"","kw":["yellow dashed line","no parking"],"img":"M22-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/forbud-mot-att-parkera/","related":["C35","M21"]},{"id":"M23","cat":"M","sv":"Förbud mot att stanna och parkera eller att parkera","en":"Yellow zigzag line","svText":"Markeringen används som förstärkning av markeringarna M21, förbud mot att stanna och parkera, och M22, förbud mot att parkera. Avvikelse från färg får inte ske.","enText":"A yellow zigzag that reinforces markings M21 (no stopping or parking) and M22 (no parking).","tip":"","kw":["zigzag","yellow zigzag"],"img":"M23-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/forbud-mot-att-stanna-och-parkera-eller-att-parkera/","related":["M21","M22"]},{"id":"M24","cat":"M","sv":"Uppställningsplats","en":"Parking space marking","svText":"Markeringen anger gränsen för uppställningsplats för fordon. Markeringen kan vara utförd med bruten linje.","enText":"Marks the border of a space where vehicles may be placed. It can be a broken line.","tip":"","kw":["parking bay lines"],"img":"M24-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/uppstallningsplats/","related":[]},{"id":"M25","cat":"M","sv":"Gång- och cykelpil","en":"Pedestrian and cycle arrow","svText":"Markeringen visar lämplig färdväg för gående eller cyklande och förare av moped klass II.","enText":"Shows a suitable route for pedestrians or for cyclists and class II moped riders.","tip":"","kw":["path arrow"],"img":"M25-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/gang--och-cykelpil/","related":[]},{"id":"M26","cat":"M","sv":"Cykel","en":"Bicycle symbol","svText":"Markeringen visar bana eller lämplig färdväg för cyklande och förare av moped klass II.","enText":"Shows a track or a suitable route for cyclists and class II moped riders.","tip":"","kw":["bike symbol on road"],"img":"M26-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/cykel/","related":[]},{"id":"M27","cat":"M","sv":"Gående","en":"Pedestrian symbol","svText":"Markeringen visar bana eller lämplig färdväg för gående.","enText":"Shows a path or suitable route for pedestrians.","tip":"","kw":["walking symbol on road"],"img":"M27-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/gaende/","related":[]},{"id":"M28","cat":"M","sv":"Buss","en":"BUSS marking","svText":"Markeringen visar att körfältet är avsett för fordon i linjetrafik med flera.","enText":"Shows that the lane is meant for buses in scheduled service and others allowed there.","tip":"","kw":["bus lane text","BUSS"],"img":"M28-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/buss/","related":["D10"]},{"id":"M29","cat":"M","sv":"Hastighet","en":"Speed limit marking","svText":"Markeringen upplyser om högsta tillåtna hastighet.","enText":"Painted on the road to remind you of the speed limit.","tip":"","kw":["speed number on road","30 painted"],"img":"M29-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/hastighet/","related":["C31"]},{"id":"M30","cat":"M","sv":"Vägnummer","en":"Road number marking","svText":"Markeringen upplyser om vägnummer.","enText":"Shows the road number painted on the road.","tip":"","kw":["E4 on road"],"img":"M30","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/vagnummer/","related":[]},{"id":"M31","cat":"M","sv":"Ändamålsplats","en":"Purpose place marking","svText":"Markeringen upplyser om en uppställningsplats som är avsedd för ett visst ändamål. Texten anpassas efter ändamålet.","enText":"Shows that a parking space is meant for a certain purpose, for example LASTPLATS (loading place). The text matches the purpose.","tip":"","kw":["loading place text"],"img":"M31-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/andamalsplats/","related":["C40"]},{"id":"M32","cat":"M","sv":"Stopp","en":"STOPP marking","svText":"Markeringen upplyser om stopplikt. Markeringen används tillsammans med märke B2, stopplikt, för att förstärka anvisningen.","enText":"The word STOPP painted on the road. Used together with sign B2 to reinforce the duty to stop.","tip":"","kw":["stop painted"],"img":"M32-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/stopp/","related":["B2"]},{"id":"M33","cat":"M","sv":"Rörelsehindrad","en":"Disabled parking marking","svText":"Markeringen upplyser om uppställningsplats endast för rörelsehindrade.","enText":"Shows a parking space only for people with reduced mobility (with a disabled parking permit).","tip":"","kw":["wheelchair symbol","disabled bay"],"img":"M33-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/rorelsehindrad/","related":[]},{"id":"M34","cat":"M","sv":"Information","en":"Information marking","svText":"Markeringen ger upplysning, varning eller vägledning av vikt för trafikanten.","enText":"Text painted on the road that gives information, a warning or guidance that matters to road users, for example SKOLA (school).","tip":"","kw":["SKOLA","text on road"],"img":"M34-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/vagmarkeringar/information/","related":[]},{"id":"P1","cat":"P","sv":"Stopp","en":"Police – stop (arm stretched out)","svText":"Tecknet anger stopp för den trafikant som kommer framifrån eller bakifrån. Tecknet används i vägkorsning och gäller så länge polismannen vänder sig åt samma håll. För trafikanter som kommer från sidan betyder tecknet att vägen är fri och att det är tillåtet att köra. Tecknet får ges i kombination med tecken P2, stopp. Tecknet kan ges med en stoppspade.","enText":"Stop for road users coming from in front of or behind the police officer. It is used in junctions and applies as long as the officer faces the same way. For road users coming from the side, it means the way is clear and they may drive. It can be combined with P2 and given with a stop paddle.","tip":"Think of the officer as a closed gate facing you, and an open gate from the side.","kw":["police officer","traffic police","arm out"],"img":"P1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/stopp/","related":["P2","P4"]},{"id":"P2","cat":"P","sv":"Stopp","en":"Police – stop (raised hand)","svText":"Tecknet anger stopp för den trafikant som handflatan är vänd mot. Tecknet kan ges med en stoppspade.","enText":"Stop for the road user that the palm of the hand is facing. It can be given with a stop paddle.","tip":"","kw":["police hand","stop"],"img":"P2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/stopp1/","related":["P1"]},{"id":"P3","cat":"P","sv":"Stopp","en":"Police – stop (lamp)","svText":"Tecknet anger stopp för den trafikant som lyktan är vänd mot. Tecknet används under mörker och vid nedsatt sikt. Lyktan hålls i den position där den lättast uppfattas av trafikanter.","enText":"Stop for the road user that the lamp is facing. Used in darkness and when visibility is poor; the lamp is held where it is easiest to see.","tip":"","kw":["police torch","red lamp"],"img":"P3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/stopp2/","related":["P2"]},{"id":"P4","cat":"P","sv":"Kör fram","en":"Police – drive on","svText":"Tecknet anger att trafikanter i den färdriktning som tecknet ges får fortsätta framåt. Tecknet ges med en vinkande rörelse i färdriktningen.","enText":"Road users in the direction of the officer's waving movement may continue.","tip":"","kw":["wave on","proceed"],"img":"P4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/kor-fram/","related":["P1"]},{"id":"P5","cat":"P","sv":"Minska hastigheten","en":"Police – slow down","svText":"Tecknet anger att den trafikant som polismannen är vänd mot ska minska hastigheten. Under mörker och vid nedsatt sikt kan tecknet vara förtydligat med en lykta som visar vitt eller gult ljus eller en reflexanordning som återkastar vitt eller gult ljus.","enText":"The road user the officer is facing must reduce speed. In darkness or poor visibility it can be made clearer with a lamp or reflector showing white or yellow light.","tip":"","kw":["slow down signal"],"img":"P5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/minska-hastigheten/","related":["P8","P9"]},{"id":"P6","cat":"P","sv":"Kontroll","en":"Control point","svText":"Tecknet anger att fordonsförare ska köra in på kontrollplats för kontroll. Visas symbol för visst eller vissa slag av fordon enligt 2 kap. 28 § gäller skyldigheten att köra in för kontroll endast för förare av dessa fordon. Tecknet är anpassat till förhållandena på platsen.","enText":"Drivers must drive into the control point to be checked. If a symbol for a vehicle type is shown, only drivers of those vehicles must drive in.","tip":"","kw":["police check","inspection","kontroll"],"img":"P6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/kontroll/","related":["P7"]},{"id":"P7","cat":"P","sv":"Förberedande upplysning om kontroll","en":"Control point ahead","svText":"Tecknet ger förberedande upplysning om kontroll. Tecknet är anpassat till förhållandena på platsen.","enText":"Advance notice of a control point.","tip":"","kw":["checkpoint ahead"],"img":"P7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/forberedande-upplysning-om-kontroll/","related":["P6"]},{"id":"P8","cat":"P","sv":"Minska hastigheten","en":"Police vehicle – slow down (traffic behind)","svText":"Tecknet anger att de trafikanter som befinner sig bakom polisfordonet ska minska hastigheten. Under mörker och vid nedsatt sikt får tecknet förtydligas med en lykta som visar vitt eller gult ljus eller en reflexanordning som återkastar vitt eller gult ljus.","enText":"Road users behind the police vehicle must reduce speed. In darkness it can be made clearer with white or yellow light or a reflector.","tip":"","kw":["police car","slow down"],"img":"P8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/minska-hastigheten1/","related":["P9","P5"]},{"id":"P9","cat":"P","sv":"Minska hastigheten","en":"Police vehicle – slow down (oncoming traffic)","svText":"Tecknet anger att de trafikanter som möter polisfordonet ska minska hastigheten. Under mörker och vid nedsatt sikt får tecknet förtydligas med en lykta som visar vitt eller gult ljus eller en reflexanordning som återkastar vitt eller gult ljus.","enText":"Road users meeting the police vehicle must reduce speed. In darkness it can be made clearer with white or yellow light or a reflector.","tip":"","kw":["police car","slow down"],"img":"P9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/minska-hastigheten2/","related":["P8","P5"]},{"id":"P10","cat":"P","sv":"Följ efter och stanna bakom polisfordonet när detta stannar","en":"Police vehicle – follow and stop behind it","svText":"Tecknet anger att föraren av det fordon som befinner sig bakom polisfordonet ska följa efter det och stanna när polisfordonet stannar. Tecknet kan ges med en stoppspade.","enText":"The driver of the vehicle behind the police vehicle must follow it and stop when it stops. It can be given with a stop paddle.","tip":"","kw":["follow me","police car"],"img":"P10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/folj-efter-och-stanna-bakom-polisfordonet-nar-detta-stannar/","related":["P11"]},{"id":"P11","cat":"P","sv":"Kör in till vägkanten och stanna framför polisfordonet","en":"Police vehicle – pull over and stop in front","svText":"Tecknet anger att föraren av det fordon som befinner sig framför polisfordonet ska köra in till vägkanten och stanna. Tecknet ges med växelvis blinkande blått och rött ljus.","enText":"The driver of the vehicle in front of the police vehicle must pull over to the side of the road and stop. The signal is given with blue and red lights flashing alternately.","tip":"Indicate, pull over where it is safe, stop and stay in the vehicle unless told otherwise.","kw":["pulled over","blue and red lights","police stop"],"img":"P11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-polisman-med-flera/kor-in-till-vagkanten-och-stanna-framfor-polisfordonet/","related":["P10"]},{"id":"S1","cat":"S","sv":"Tung lastbil","en":"Heavy truck","svText":"","enText":"Symbol for a heavy truck (total weight over 3,500 kg), used on direction signs and panels.","tip":"","kw":["lorry symbol"],"img":"S1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/tung-lastbil/","related":[]},{"id":"S2","cat":"S","sv":"Tung lastbil med tillkopplad släpvagn","en":"Heavy truck with trailer","svText":"","enText":"Symbol for a heavy truck with a trailer.","tip":"","kw":["truck and trailer"],"img":"S2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/tung-lastbil-med-tillkopplad-slapvagn/","related":[]},{"id":"S3","cat":"S","sv":"Personbil","en":"Passenger car","svText":"","enText":"Symbol for a passenger car.","tip":"","kw":["car symbol"],"img":"S3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/personbil/","related":[]},{"id":"S4","cat":"S","sv":"Personbil med tillkopplad släpkärra","en":"Passenger car with light trailer","svText":"","enText":"Symbol for a passenger car towing a light trailer (släpkärra).","tip":"","kw":["car and trailer"],"img":"S4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/personbil-med-tillkopplad-slapkarra/","related":[]},{"id":"S5","cat":"S","sv":"Buss","en":"Bus","svText":"","enText":"Symbol for a bus.","tip":"","kw":["bus symbol"],"img":"S5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/buss/","related":[]},{"id":"S6","cat":"S","sv":"Traktor och motorredskap klass II","en":"Tractor and class II motor implement","svText":"","enText":"Symbol for tractors and class II motor implements (machines built for at most 30 km/h).","tip":"","kw":["tractor symbol"],"img":"S6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/traktor-och-motorredskap-klass-ii/","related":[]},{"id":"S7","cat":"S","sv":"Motorcykel","en":"Motorcycle","svText":"Symbolen anger tvåhjulig motorcykel utan sidvagn och tvåhjulig moped klass I utan sidvagn.","enText":"Symbol for a two-wheeled motorcycle without a sidecar and a two-wheeled class I moped without a sidecar.","tip":"","kw":["motorbike symbol","MC"],"img":"S7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/motorcykel/","related":[]},{"id":"S8","cat":"S","sv":"Cykel och moped klass II","en":"Bicycle and class II moped","svText":"","enText":"Symbol for bicycles and class II mopeds.","tip":"","kw":["bike symbol"],"img":"S8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/cykel-och-moped-klass-ii/","related":[]},{"id":"S9","cat":"S","sv":"Släpkärra","en":"Light trailer","svText":"","enText":"Symbol for a light trailer of the kind called släpkärra.","tip":"","kw":["trailer symbol"],"img":"S9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/slapkarra/","related":[]},{"id":"S10","cat":"S","sv":"Gående","en":"Pedestrians","svText":"","enText":"Symbol for pedestrians.","tip":"","kw":["walkers"],"img":"S10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/gaende/","related":[]},{"id":"S11","cat":"S","sv":"Rörelsehindrade","en":"People with reduced mobility","svText":"","enText":"Symbol for people with reduced mobility.","tip":"","kw":["wheelchair","disabled"],"img":"S11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/rorelsehindrade/","related":[]},{"id":"S12","cat":"S","sv":"Personbil klass II","en":"Motorhome","svText":"","enText":"Symbol for a class II passenger car – a car with a permanent living area (motorhome).","tip":"","kw":["camper van","husbil"],"img":"S12-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/personbil-klass-ii/","related":[]},{"id":"S13","cat":"S","sv":"Personfärja","en":"Passenger ferry","svText":"Symbolen anger ett färjeläge för personfärja eller att angivet färdmål endast kan nås med färja avsedd för persontransport.","enText":"Symbol for a terminal for a passenger ferry, or showing that the destination can only be reached by a ferry for passengers.","tip":"","kw":["foot ferry"],"img":"S13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/symboler/personfarja/","related":[]},{"id":"T1","cat":"T","sv":"Vägsträckas längd","en":"Length of stretch","svText":"Tavlan anger början och slutet på en vägsträcka.","enText":"Shows where a stretch begins and ends, measured from the sign. For example \"200–800 m\" means the sign above applies from 200 metres ahead to 800 metres ahead; \"0–1.2 km\" means it applies from here for 1.2 kilometres.","tip":"","kw":["stretch length","distance range"],"img":"T1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/vagstrackas-langd/","related":["T2"]},{"id":"T2","cat":"T","sv":"Avstånd","en":"Distance","svText":"Tavlan anger avståndet till det som vägmärket avser.","enText":"Shows the distance to what the sign above refers to – for example to a danger, a ban or a give-way point.","tip":"","kw":["distance ahead","meters"],"img":"T2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/avstand/","related":["T1","T3"]},{"id":"T3","cat":"T","sv":"Avstånd till stopplikt","en":"Distance to stop sign","svText":"Tavlan används endast under märke B1, väjningsplikt.","enText":"Used only under sign B1 (give way). It warns that there is a stop sign (stopplikt) at the distance shown.","tip":"When you see this panel, be ready to stop completely at the junction ahead.","kw":["stop ahead","STOPP 200 m"],"img":"T3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/avstand-till-stopplikt/","related":["B1","B2","T2"]},{"id":"T4","cat":"T","sv":"Fri bredd","en":"Free width","svText":"","enText":"Shows the free width of the road, for example where the road narrows.","tip":"","kw":["width","road width"],"img":"T4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/fri-bredd/","related":[]},{"id":"T5","cat":"T","sv":"Totalvikt","en":"Total weight","svText":"Tavlan anger att angivelsen på märket gäller fordon med en totalvikt som överstiger det angivna värdet.","enText":"The sign above applies only to vehicles with a total weight (the highest weight the vehicle is registered for) above the value shown.","tip":"Total weight is the registered maximum weight, not what the vehicle weighs today. A light truck with a total weight of 3.5 t is not covered by a ban for vehicles over 3.5 t.","kw":["weight","tonnes","totalvikt"],"img":"T5","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/totalvikt/","related":["C20"]},{"id":"T6","cat":"T","sv":"Tidsangivelse","en":"Times","svText":"Tavlan anger när angivelsen på vägmärket gäller. Används klockslag i kombination med andra villkor anger tavlan även när dessa villkor gäller. Svarta eller vita siffror utan parentes avser vardagar utom vardag före sön- och helgdag. Svarta eller vita siffror inom parentes avser vardag före sön- och helgdag. Röda siffror avser sön- och helgdag. Om angivelsen sträcker sig över midnatt gäller tidsperioden efter midnatt påföljande dag. Anges viss dag eller viss veckodag gäller regleringen denna dag oavsett om dagen är en vardag, söndag eller helgdag.","enText":"Shows when the sign above applies. Black or white numbers without brackets mean weekdays except the day before a Sunday or public holiday. Numbers in brackets mean the day before a Sunday or public holiday (usually Saturday). Red numbers mean Sundays and public holidays. If a period runs past midnight, the part after midnight belongs to the next day. If a particular date or weekday is given, the rule applies that day whatever kind of day it is.","tip":"Example: 8–17, (8–14), 8–13 in red means Monday–Friday 8–17, Saturday 8–14, Sunday and holidays 8–13.","kw":["time panel","hours","weekdays","Saturday","Sunday","red numbers","brackets"],"img":"T6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/tidsangivelse/","related":[]},{"id":"T7","cat":"T","sv":"Rörelsehindrade","en":"Disabled parking permit","svText":"Tavlan anger att angivelsen på märket gäller den som får parkera enligt ett parkeringstillstånd som avses i 13 kap. 8 eller 9 § trafikförordningen. Tavlan används endast under märke E19, parkering. Anges tid med tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"Used only under sign E19 (parking). The parking applies to people who may park with a parking permit for people with disabilities. Times on panel T6 work as usual.","tip":"","kw":["disabled parking","handicap parking","wheelchair"],"img":"T7","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/rorelsehindrade/","related":["E19","T8"]},{"id":"T8","cat":"T","sv":"Symboltavla","en":"Vehicle type or road user panel","svText":"Tavlan anger att det märke som tavlan är uppsatt under endast gäller för det fordonsslag eller den trafikantgrupp som anges på tavlan. Fordonsslaget eller trafikantgruppen anges med symbol enligt 28 §. Anges tid enligt tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"The sign above applies only to the vehicle type or road user group shown by the symbol. Times on panel T6 work as usual.","tip":"For example, sign C27 (no overtaking) with a truck panel applies only to heavy trucks; a P sign with a car panel means parking only for cars.","kw":["vehicle symbol","applies only to","truck panel"],"img":"T8-1","variants":[{"key":"T8-2","en":"Heavy trucks with a trailer"},{"key":"T8-3","en":"Passenger cars"},{"key":"T8-4","en":"Passenger cars with a light trailer"},{"key":"T8-5","en":"Buses"},{"key":"T8-6","en":"Tractors and class II motor implements"},{"key":"T8-7","en":"Motorcycles and class I mopeds (two-wheeled, without sidecar)"},{"key":"T8-8","en":"Bicycles and class II mopeds"},{"key":"T8-9","en":"Light trailers (släpkärra)"},{"key":"T8-10","en":"Pedestrians"},{"key":"T8-11","en":"People with reduced mobility"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/symboltavla/","related":[]},{"id":"T9","cat":"T","sv":"Nedsatt syn","en":"People with impaired sight","svText":"Tavlan anger att personer med nedsatt syn är vanligt förekommande.","enText":"Shows that people with impaired sight are often found here.","tip":"","kw":["blind people","visually impaired"],"img":"T9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/nedsatt-syn/","related":["T10"]},{"id":"T10","cat":"T","sv":"Nedsatt hörsel","en":"People with impaired hearing","svText":"Tavlan anger att personer med nedsatt hörsel är vanligt förekommande. Tavlan har alltid gul bottenfärg.","enText":"Shows that people with impaired hearing are often found here. This panel is always yellow.","tip":"","kw":["deaf people","hearing impaired"],"img":"T10","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/nedsatt-horsel/","related":["T9"]},{"id":"T11","cat":"T","sv":"Utsträckning","en":"Extent","svText":"Tavlan med dubbelriktade pilar, uppsatt vågrätt eller lodrätt, anger att angivelsen gäller på båda sidor av märket. Tavlan med nedåtriktad pil anger att angivelsen slutar. Tavlan med höger- eller vänsterriktad pil visar att angivelsen gäller åt det håll pilen visar. Används tavlan under märke E19, parkering, har den svarta tecken på vit botten utan bård. Tavlorna kan även användas fristående för att ange avgränsning av uppställningsplatser på ett område, om det vid infarten till området anges att parkering är tillåten.","enText":"A panel with arrows pointing both ways (horizontal or vertical) means the rule applies on both sides of the sign. An arrow pointing down means the rule ends here. An arrow to the right or left shows that the rule applies in that direction. Under a parking sign (E19) it has black arrows on white without a border.","tip":"","kw":["arrow panel","ends here","both sides","utsträckning"],"img":"T11-1","variants":[{"key":"T11-2","en":"Rule ends here (arrow pointing down)"},{"key":"T11-3","en":"Rule applies in the direction of the arrow"},{"key":"T11-4","en":"Rule applies to the left (under a parking sign)"},{"key":"T11-5","en":"Rule applies to the right (under a parking sign)"},{"key":"T11-6","en":"Rule applies on both sides (yellow, under a no-parking sign)"},{"key":"T11-7","en":"Rule applies on both sides (vertical, yellow)"},{"key":"T11-8","en":"Rule ends here (yellow, under a no-parking sign)"},{"key":"T11-9","en":"Rule applies to the left (yellow)"},{"key":"T11-10","en":"Rule applies to the right (yellow)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/utstrackning/","related":[]},{"id":"T12","cat":"T","sv":"Riktning","en":"Direction","svText":"Tavlan anger riktning till angivelsen på märket.","enText":"Shows the direction to what the sign above refers to.","tip":"","kw":["direction arrow"],"img":"T12-1","variants":[{"key":"T12-2","en":"Direction (half right)"},{"key":"T12-3","en":"Direction (straight ahead)"},{"key":"T12-4","en":"Direction (half left)"},{"key":"T12-5","en":"Direction (left)"},{"key":"T12-6","en":"Direction (to the left)"},{"key":"T12-7","en":"Direction (to the right)"},{"key":"T12-8","en":"Direction (both ways)"},{"key":"T12-9","en":"Direction (straight ahead and left)"},{"key":"T12-10","en":"Direction (straight ahead and right)"},{"key":"T12-11","en":"Direction (diagonally right)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/t12-riktning/","related":[]},{"id":"T13","cat":"T","sv":"Flervägsväjning","en":"All-way give way","svText":"Tavlan anger att förare på samtliga tillfarter i en korsning har väjningsplikt.","enText":"Shows that drivers on every road into the junction have to give way.","tip":"When everyone has to give way, the right-hand rule decides between drivers who arrive at the same time.","kw":["all-way yield","flervägsväjning"],"img":"T13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/flervagsvajning/","related":["T14","B1"]},{"id":"T14","cat":"T","sv":"Flervägsstopp","en":"All-way stop","svText":"Tavlan anger att förare på samtliga tillfarter i en korsning har stopplikt.","enText":"Shows that drivers on every road into the junction must stop.","tip":"After stopping, the right-hand rule decides who goes first if several drivers arrive at the same time.","kw":["all-way stop","four-way stop","flervägsstopp"],"img":"T14-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/flervagsstopp/","related":["T13","B2"]},{"id":"T15","cat":"T","sv":"Vägars fortsättning i korsning","en":"How the roads continue in the junction","svText":"Tavlan anger en korsning där förare på en väg som anges med smalt streck har väjningsplikt mot fordon på en väg som anges med brett streck. Symbolen är anpassad efter förhållandena på platsen.","enText":"Shows a junction where drivers on the road drawn with a narrow line must give way to vehicles on the road drawn with a wide line. The symbol is drawn to match the place.","tip":"This panel is common under a main road sign where the main road turns. The wide line shows where the priority road goes.","kw":["priority road turns","main road bends"],"img":"T15-1","variants":[{"key":"T15-2","en":"Another junction layout"},{"key":"T15-3","en":"Another junction layout"},{"key":"T15-4","en":"Another junction layout"},{"key":"T15-5","en":"Another junction layout"},{"key":"T15-6","en":"Another junction layout"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/vagars-fortsattning-i-korsning/","related":["B4","B1"]},{"id":"T16","cat":"T","sv":"Avgift","en":"Fee","svText":"Tavlan anger att avgift ska betalas för parkering enligt den taxa som anges på en parkeringsmätare, biljettautomat eller motsvarande och att övriga villkor för parkering som anges där ska iakttas. Anges tid enligt tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"Parking costs money according to the price list on the parking meter, ticket machine or similar, and any other conditions written there must be followed. Times on panel T6 work as usual.","tip":"","kw":["paid parking","avgift","parking meter"],"img":"T16","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/avgift/","related":["E19","T20"]},{"id":"T17","cat":"T","sv":"Parkeringsskiva","en":"Parking disc","svText":"Tavlan anger att tiden när parkering påbörjats ska anges med en parkeringsskiva eller motsvarande. Anges tid enligt tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"You must show the time you started parking with a parking disc (P-skiva) or similar. Times on panel T6 work as usual.","tip":"Set the disc to the next half hour after you arrive. Arrive at 10:10 and you set 10:30.","kw":["parking disc","P-skiva","parkeringsskiva"],"img":"T17-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/parkeringsskiva/","related":["T18"]},{"id":"T18","cat":"T","sv":"Tillåten tid för parkering","en":"Time limit for parking","svText":"Tavlan anger längsta tillåten tid för parkering. Anges tid enligt tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"Shows the longest time you may park. Times on panel T6 work as usual.","tip":"","kw":["max parking time","2 tim","hours"],"img":"T18","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/tillaten-tid-for-parkering/","related":["T17"]},{"id":"T19","cat":"T","sv":"Boende","en":"Residents","svText":"Tavlan anger att boende i ett område, med särskilt tillstånd, får parkera enligt särskilda villkor. Texten kan vara kompletterad med områdesbeteckning eller motsvarande. Anges tid enligt tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"Residents of an area who have a special permit may park under special conditions. An area code may be added. Times on panel T6 work as usual.","tip":"","kw":["resident parking","boende"],"img":"T19","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/boende/","related":[]},{"id":"T20","cat":"T","sv":"Parkeringsbiljett","en":"Parking ticket","svText":"Tavlan anger att parkering är avgiftsfri men att parkeringsbiljett ska användas vid parkering. Anges tid enligt tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"Parking is free of charge, but you must use a parking ticket. Times on panel T6 work as usual.","tip":"","kw":["free ticket","P-biljett"],"img":"T20","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/parkeringsbiljett/","related":["T16"]},{"id":"T21","cat":"T","sv":"Uppställning av fordon","en":"How to park","svText":"Tavlan anger hur fordon ska ställas upp på en parkeringsplats. Tavlan är anpassad efter förhållandena på platsen.","enText":"Shows how vehicles must be placed in a car park – for example at right angles, in a line, or at an angle. The panel is drawn to match the place.","tip":"","kw":["parking layout","angle parking"],"img":"T21-1","variants":[{"key":"T21-2","en":"Park in a line along the road"},{"key":"T21-3","en":"Park at an angle"},{"key":"T21-4","en":"Park at an angle (other direction)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/uppstallning-av-fordon/","related":[]},{"id":"T22","cat":"T","sv":"Text","en":"Text panel","svText":"Tavlan ger kompletterande anvisning som inte kan ges med någon annan tilläggstavla eller kombinationer av dessa. Anges tid enligt tavla T6, tidsangivelse, gäller den kompletterande anvisningen enligt de närmare föreskrifterna till tavlan T6, tidsangivelse.","enText":"Gives an extra instruction in words that no other panel, or combination of panels, can give. Times on panel T6 work as usual.","tip":"","kw":["text","written panel"],"img":"T22-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/text/","related":[]},{"id":"T23","cat":"T","sv":"Tunnelkategori","en":"Tunnel category","svText":"Tavlan används under märke C9, förbud mot trafik med fordon lastat med farligt gods. Bokstaven B, C, D eller E anger tunnelns kategori. Klockslag kan anges på tavlan enligt de närmare föreskrifterna till tilläggstavla T6, tidsangivelse.","enText":"Used under sign C9 (no vehicles with dangerous goods). The letter B, C, D or E gives the tunnel's category, which decides which dangerous goods are banned. Times may be shown.","tip":"","kw":["tunnel category","dangerous goods"],"img":"T23-1","variants":[{"key":"T23-2","en":"Tunnel category C"},{"key":"T23-3","en":"Tunnel category D"},{"key":"T23-4","en":"Tunnel category E"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/tunnelkategori/","related":["C9"]},{"id":"T24","cat":"T","sv":"Laddplats","en":"Charging place","svText":"Tavlan anger en plats för extern laddning av elektricitet för fordons framdrivning. Tavlan används under märke E19, parkering, och anger att endast fordon med möjlighet till extern laddning av elektricitet för fordonets framdrivning får parkera.","enText":"Used under sign E19 (parking). It marks a place for charging electric vehicles, where only vehicles that can be charged from an external source may park.","tip":"A petrol or diesel car may not park here, not even for a short time; it may only stop to let people get in or out.","kw":["EV charging","electric car parking","laddplats"],"img":"T24-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/laddplats/","related":["E19","H27"]},{"id":"T25","cat":"T","sv":"Öppet dygnet runt","en":"Open 24 hours","svText":"Tavlan anger att en servering eller restaurang är öppen dygnet runt. Tavlan används under något av märkena H5, servering, eller H6, restaurang.","enText":"Shows that a café or restaurant is open around the clock. It is used under sign H5 or H6.","tip":"","kw":["24 hours","open all night"],"img":"T25-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tillaggstavlor/oppet-dygnet-runt/","related":[]},{"id":"SIG1","cat":"SIG","sv":"Röd","en":"Red light","svText":"Stopp. Fordon får inte passera stopplinjen eller, om sådan saknas, signalen. Signal med konturpil gäller endast den eller de färdriktningar som anges med pilen.","enText":"Stop. Vehicles may not pass the stop line, or the signal if there is no stop line. A red arrow outline in the lamp means the red light only applies to the direction of the arrow.","tip":"","kw":["red light","stop light","rött ljus","traffic light"],"img":"SIG1-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/rod/","related":["SIG2","SIG4"]},{"id":"SIG2","cat":"SIG","sv":"Röd + gul","en":"Red and yellow light","svText":"Växling till grön signalbild är omedelbart förestående. I övrigt har signalbilden samma innebörd som röd.","enText":"The light is about to turn green. Otherwise it means the same as red – you may not drive yet.","tip":"","kw":["red amber","red yellow"],"img":"SIG2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/rod--gul/","related":["SIG1","SIG3"]},{"id":"SIG3","cat":"SIG","sv":"Grön","en":"Green light","svText":"Fordon får fortsätta framåt. Grön pil innebär att signalen gäller den färdriktning som anges med pilen. Fordon får föras i pilens riktning även om en annan signalbild visas samtidigt.","enText":"Vehicles may go ahead. A green arrow means the signal applies to the direction of the arrow, and you may drive in that direction even if another light is showing at the same time.","tip":"Green does not mean the way is clear. When you turn, you must still give way to pedestrians and cyclists crossing the road you turn into.","kw":["green light","go"],"img":"SIG3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/gron/","related":["SIG1"]},{"id":"SIG4","cat":"SIG","sv":"Gul","en":"Yellow light","svText":"Stanna. Fordon får inte passera stopplinjen eller, om sådan saknas, signalen i annat fall än då det hunnit så långt fram när signalbilden växlar från grön till gul att det inte kan stannas utan fara. Signal med konturpil gäller endast den eller de färdriktningar som anges med pilen.","enText":"Stop. Vehicles may not pass the stop line (or the signal) unless they were so close when the light changed from green to yellow that they cannot stop safely.","tip":"","kw":["amber light","yellow light","gult ljus"],"img":"SIG4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/gul/","related":["SIG1","SIG5"]},{"id":"SIG5","cat":"SIG","sv":"Blinkande gul","en":"Flashing yellow light","svText":"Särskild försiktighet ska iakttas vid passage.","enText":"Take special care when passing. It is shown only when the signals are out of order or temporarily not working for a short time; the normal priority rules and signs then apply.","tip":"","kw":["flashing amber","signals out of order"],"img":"SIG5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/blinkande-gul/","related":["SIG4","SIG18"]},{"id":"SIG6","cat":"SIG","sv":"Röd akustisk signal med långsam pulsfrekvens","en":"Red pedestrian light","svText":"Förbjudet att beträda en körbana, cykelbana eller järnvägs- eller spårvägskorsning. Gående som befinner sig på körbanan eller cykelbanan när signalen slår om till röd signalbild skall fortsätta till andra sidan. Finns en refug eller liknande anordning skall den gående dock stanna där.","enText":"A standing figure, often with a slow ticking sound. Pedestrians may not step onto the carriageway, cycle track or crossing. Someone already on the road when it turns red should continue to the other side, or stop on a refuge if there is one.","tip":"","kw":["red man","don't walk"],"img":"SIG6-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/rod-akustisk-signal-med-langsam-pulsfrekvens/","related":["SIG7"]},{"id":"SIG7","cat":"SIG","sv":"Grön akustisk signal med snabb pulsfrekvens","en":"Green pedestrian light","svText":"Körbana, cykelbana eller järnvägs- eller spårvägskorsning får beträdas.","enText":"A walking figure, often with a fast ticking sound. Pedestrians may cross. A flashing green figure (with a fast sound with breaks) means it will soon turn red.","tip":"As a driver turning at a junction, you must let pedestrians cross on a green pedestrian light.","kw":["green man","walk signal"],"img":"SIG7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/gron-akustisk-signal-med-snabb-pulsfrekvens/","related":["SIG6"]},{"id":"SIG8","cat":"SIG","sv":"S","en":"Public transport signal \"S\"","svText":"Stopp. Fordon och spårvagn får inte passera stopplinjen, eller om sådan saknas, signalen.","enText":"Stop. A white S in a signal for buses and trams. It applies to vehicles in scheduled service and trams – and to everyone using a bus lane where the signal stands by that lane.","tip":"","kw":["bus signal","tram signal","kollektivtrafiksignal"],"img":"SIG8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/s/","related":["SIG9","SIG10","SIG11"]},{"id":"SIG9","cat":"SIG","sv":"S+vågrätt streck","en":"Public transport signal \"S\" with a horizontal bar","svText":"Växling till lodrätt streck är omedelbart förestående. I övrigt har signalbilden samma innebörd som S.","enText":"The signal is about to show the vertical bar (go). Otherwise it means the same as S – stop.","tip":"","kw":["bus signal"],"img":"SIG9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/svagratt-streck/","related":["SIG8"]},{"id":"SIG10","cat":"SIG","sv":"Lodrätt streck eller pil","en":"Public transport signal with a vertical bar or arrow","svText":"Fordon och spårvagn får fortsätta framåt. Pil innebär att signalen gäller den färdriktning som anges med pilen.","enText":"Go. Buses and trams may continue. An arrow means it applies to that direction.","tip":"","kw":["bus signal go"],"img":"SIG10-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/lodratt-streck-eller-pil/","related":["SIG8"]},{"id":"SIG11","cat":"SIG","sv":"Vågrätt streck","en":"Public transport signal with a horizontal bar","svText":"Stanna. Fordon och spårvagn får inte passera stopplinjen, eller om sådan saknas, signalen i annat fall än då det hunnit så långt fram när signalen växlar från lodrätt till vågrätt streck att det inte kan stannas utan fara.","enText":"Stop, unless the vehicle was so close when the signal changed from a vertical to a horizontal bar that it cannot stop safely. A flashing horizontal bar means take special care.","tip":"","kw":["bus signal stop"],"img":"SIG11-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/vagratt-streck/","related":["SIG8"]},{"id":"SIG12","cat":"SIG","sv":"Rött kryss","en":"Lane signal – red cross","svText":"Körfältet och i förekommande fall vägrenen intill körfältet får inte användas för trafik.","enText":"A red cross above a lane means the lane, and the shoulder next to it, may not be used.","tip":"Common on motorways and in tunnels when a lane is closed because of an accident or road works.","kw":["lane closed","red X","motorway gantry"],"img":"SIG12-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/rott-kryss/","related":["SIG13","SIG14"]},{"id":"SIG13","cat":"SIG","sv":"Gul pil eller pilar","en":"Lane signal – yellow arrow","svText":"Föraren skall byta körfält i den riktning pilen eller pilarna anger.","enText":"A yellow diagonal arrow (or arrows) above a lane means you must change to another lane in the direction shown.","tip":"","kw":["lane change arrow","move over"],"img":"SIG13-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/gul-pil-eller-pilar/","related":["SIG12","SIG14"]},{"id":"SIG14","cat":"SIG","sv":"Grön pil","en":"Lane signal – green arrow","svText":"Körfältet får användas för trafik. I stället för grön pil kan ett vägmärke förekomma.","enText":"A green arrow pointing down above a lane means the lane may be used. A road sign may be shown instead of the green arrow.","tip":"","kw":["lane open"],"img":"SIG14-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/gron-pil/","related":["SIG12","SIG13"]},{"id":"SIG16","cat":"SIG","sv":"Rött blinkande ljus","en":"Flashing red lights (bridge, fire station, tunnel …)","svText":"Stopp. Trafikanter får inte passera stopplinjen eller, om sådan saknas, signalen.","enText":"Two red lights flashing alternately mean stop. You may not pass the stop line, or the signal. They are used where a road is temporarily closed, for example at an opening bridge, a fire or ambulance station, an airfield, road works or a tunnel. A ringing sound may be added.","tip":"","kw":["alternating red lights","bridge signal"],"img":"SIG16-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/rott-blinkande-ljus2/","related":["Y1"]},{"id":"SIG17","cat":"SIG","sv":"Rött fast ljus","en":"Steady red light (road closed)","svText":"Signalen anger att en väg är helt avstängd.","enText":"A steady red light means the road is completely closed.","tip":"","kw":["road closed light"],"img":"SIG17-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/rott-fast-ljus/","related":[]},{"id":"SIG18","cat":"SIG","sv":"Gult blinkande ljus för påkallande av särskild försiktighet","en":"Flashing yellow light (take special care)","svText":"Signalen används där en väg är delvis avstängd eller för att det ska vara lättare att upptäcka ett vägmärke eller en annan anordning. Antalet ljusöppningar och deras placering är anpassade till den anordning signalen är placerad vid. Signalen kan användas fristående eller tillsammans med en anordning som avger ljud för att ge anvisning för gående om korsande spårvagn eller buss.","enText":"Used where a road is partly closed, or to make a sign or other device easier to notice. It can also be combined with a sound to warn pedestrians of a crossing tram or bus.","tip":"","kw":["flashing amber beacon","caution light"],"img":"SIG18-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/trafiksignaler/gult-blinkande-ljus-for-pakallande-av-sarskild-forsiktighet/","related":["SIG5"]},{"id":"V1","cat":"V","sv":"Stopp","en":"Guard – stop","svText":"Tecknet anger stopp för den trafikant vakten är vänd mot. Under mörker ges tecknet med lykta med rött ljus. Tecknet får också ges med märke C34, stopp för angivet ändamål, med texten Vakt.","enText":"Stop for the road user the guard is facing. In darkness it is given with a lamp showing red light. It can also be given with sign C34 with the text VAKT (guard).","tip":"","kw":["flagman","road works guard","vakt"],"img":"V1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-vakt/stopp/","related":["V2","C34"]},{"id":"V2","cat":"V","sv":"Kör fram","en":"Guard – drive on","svText":"Tecknet anger att trafikanten får fortsätta framåt. Tecknet ges med en vinkande rörelse i färdriktningen.","enText":"The road user may continue. Given with a waving movement in the direction of travel.","tip":"","kw":["flagman wave"],"img":"V2","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-vakt/kor-fram/","related":["V1"]},{"id":"V3","cat":"V","sv":"Kännetecken","en":"Guard's identification","svText":"Kännetecken ska bäras både framtill och baktill.","enText":"A guard who directs traffic wears identification marking on both the front and the back.","tip":"","kw":["guard vest"],"img":"V3","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/tecken-av-vakt/kannetecken/","related":[]},{"id":"X1","cat":"X","sv":"Markeringspil","en":"Marker arrow","svText":"Anordningen anger att fordonsförare måste svänga kraftigt i den gula pilens eller de gula pilarnas riktning på grund av till exempel en kurva. Antalet pilar är anpassat till förhållandena på platsen. Om anordningen används vid ett vägarbete eller tillfälligt av någon annan anledning har den röd botten.","enText":"Yellow arrow(s) showing that drivers must turn sharply in the direction of the arrow(s), for example because of a bend. The number of arrows matches the place. At road works or other temporary places it has a red background.","tip":"","kw":["chevron sign","bend marker","markeringspil"],"img":"X1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/markeringspil/","related":["A1"]},{"id":"X2","cat":"X","sv":"Markeringsskärm för hinder","en":"Obstacle marker board","svText":"Anordningen anger att framkomligheten på vägen är inskränkt på grund av ett hinder. Anordningen kan även ange att en väg är helt eller delvis avstängd för trafik. Antalet gula fält är anpassat till hindret eller till förhållandena på platsen. Om anordningen används vid ett vägarbete eller tillfälligt av någon annan anledning har den röd botten.","enText":"Shows that the road is narrowed by an obstacle. It can also show that a road is completely or partly closed. The number of yellow fields matches the obstacle. At road works or other temporary places it has a red background.","tip":"","kw":["barrier board","obstacle marker"],"img":"X2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/markeringsskarm-for-hinder/","related":[]},{"id":"X3","cat":"X","sv":"Markeringsskärm för sidohinder, farthinder med mera","en":"Side obstacle marker","svText":"Anordningen anger vägens eller körbanans kant eller skiljer trafikriktningar åt vid komplicerade passager. Anordningen anger även att fordon ska föras på den sida som de gula fälten lutar ned mot. Om anordningen används vid ett vägarbete eller tillfälligt av någon annan anledning har den röd botten. De gula fälten kan då vara vågräta. Fordonen får då föras på båda sidor om anordningen.","enText":"Marks the edge of a road or carriageway, or separates the directions of traffic at complicated places. Vehicles must pass on the side the yellow stripes slope down towards. At road works or other temporary places it has a red background; the yellow fields may then be horizontal, and you may pass on either side.","tip":"","kw":["bollard marker","keep left marker","refuge marker"],"img":"X3-1","variants":[{"key":"X3-2","en":"Temporary version (red and yellow) – pass on the side the stripes slope towards"},{"key":"X3-3","en":"Temporary version with horizontal stripes – pass on either side"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/markeringsskarm-for-sidohinder-farthinder-mm/","related":["D2"]},{"id":"X4","cat":"X","sv":"Avfartsskärm","en":"Exit marker","svText":"Anordningen anger skiljepunkten mellan en huvudkörbana och en avfart där det finns ett retardationsfält.","enText":"Marks the split between a main carriageway and an exit that has a deceleration lane.","tip":"","kw":["gore marker","exit split"],"img":"X4-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/avfartsskarm/","related":[]},{"id":"X5","cat":"X","sv":"Gul ljuspil eller ljuspilar","en":"Yellow light arrow(s)","svText":"Anordningen anger att trafikanter ska passera på den sida pilen eller pilarna visar. Pilen eller pilarna kan vara blinkande.","enText":"Road users must pass on the side shown by the arrow or arrows, which may be flashing.","tip":"","kw":["arrow board","flashing arrows","road works"],"img":"X5-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/gul-ljuspil-eller-ljuspilar/","related":[]},{"id":"X6","cat":"X","sv":"Särskild varningsanordning","en":"Special warning device","svText":"Anordningen anger att framkomligheten på en väg är inskränkt på grund av ett tillfälligt hinder eller liknande. Texten på anordningen anpassas till orsaken.","enText":"A triangle with a text showing that the road is restricted by a temporary obstacle or similar. The text matches the reason.","tip":"","kw":["warning triangle","olycka","accident","recovery"],"img":"X6-1","variants":[{"key":"X6-2","en":"KONTROLL – a check or inspection"},{"key":"X6-3","en":"POLIS – police"},{"key":"X6-4","en":"BÄRGNING – vehicle recovery (towing)"},{"key":"X6-5","en":"LASTNING – loading"},{"key":"X6-6","en":"EFTERSÖK – search (for example for an injured animal after a collision)"}],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/sarskild-varningsanordning/","related":[]},{"id":"X7","cat":"X","sv":"Vägbom","en":"Road barrier","svText":"Anordningen anger att en väg är helt eller delvis avstängd för trafik. En bom kan vara försedd med ytterligare anordningar för att öka synbarheten.","enText":"Shows that a road is completely or partly closed to traffic. It may carry more devices to make it easier to see.","tip":"","kw":["barrier","road closed","vägbom"],"img":"X7-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/vagbom/","related":[]},{"id":"X8","cat":"X","sv":"Tillfällig stängning","en":"Temporary closure","svText":"Anordningen anger att en anvisning genom ett vägmärke om väg till ort, plats, inrättning, anläggning eller liknande tillfälligt inte gäller. Anordningen är anpassad till vägmärket.","enText":"Shows that a direction sign's information about the way to a place, facility or similar does not apply for the time being.","tip":"","kw":["crossed-out sign","temporarily closed"],"img":"X8-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/x8/","related":[]},{"id":"X9","cat":"X","sv":"Cirkulationstrafik","en":"Roundabout centre marker","svText":"Anordningen anger mittpunkten i en rondell runt vilken fordon ska föras.","enText":"Marks the centre of a roundabout, around which vehicles must drive.","tip":"","kw":["roundabout marker"],"img":"X9-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/cirkulationstrafik/","related":["D3"]},{"id":"X10","cat":"X","sv":"Stolpmarkeringsanordning","en":"Post marker","svText":"Anordningen används för att det ska vara lättare att upptäcka ett vägmärke eller en annan anordning enligt denna förordning. Anordningen är placerad på en stolpe eller motsvarande som bär upp ett vägmärke eller en annan anordning. Anordningen är anpassad till förhållandena på platsen. En stolpmarkeringsanordning har samma färgsättning som det vägmärke eller den andra anordning som den sitter under om inte Transportstyrelsen föreskriver annat.","enText":"Placed on the post of a sign or device to make it easier to notice. It usually has the same colours as the sign it sits under.","tip":"","kw":["post marking"],"img":"X10","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/andra-anordningar-for-anvisningar-for-trafiken/stolpmarkeringsanordning/","related":[]},{"id":"Y1","cat":"Y","sv":"Rött blinkande ljus","en":"Level crossing light signal","svText":"Stopp. Trafikanter får inte passera stopplinjen eller, om sådan saknas, signalen. Ljussignalen består av två ljusöppningar på samma höjd som avger växelvis blinkande rött ljus och en skärm i form av en triangel med rundade hörn och med spetsen nedåt. Skärmen kan vara försedd med vit bård. Under de röda ljusöppningarna kan det finnas en cirkulär ljusöppning, från vilken det kan avges blinkande vitt ljus för att göra korsningen lättare att upptäcka.","enText":"Two red lights flashing alternately mean stop. Road users may not pass the stop line, or the signal if there is no stop line. Below the red lights there may be a round white light that flashes to make the crossing easier to notice.","tip":"Never drive onto a level crossing while the red lights flash, the bell rings or the barriers move – even if you cannot see a train.","kw":["railway signal","flashing red","level crossing","train"],"img":"Y1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/sakerhetsanordningar-i-korsningar-med-jarnvag-eller-sparvag/rott-blinkande-ljus/","related":["Y2","Y3","A39"]},{"id":"Y2","cat":"Y","sv":"Ljudsignal","en":"Level crossing bell","svText":"","enText":"A ringing sound means stop. Road users may not pass the stop line, or the signal.","tip":"","kw":["bell","ringing","railway"],"img":"Y2-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/sakerhetsanordningar-i-korsningar-med-jarnvag-eller-sparvag/ljudsignal/","related":["Y1"]},{"id":"Y3","cat":"Y","sv":"Bom","en":"Level crossing barrier","svText":"Anordningens baksida får förses med texten ”Kör genom bommen”.","enText":"A full or half barrier. It has at least one lamp showing flashing red light towards approaching traffic from when it starts to lower until it is fully raised. The back of the barrier may have the text \"Kör genom bommen\" (drive through the barrier).","tip":"If you get trapped between the barriers, drive straight out through the barrier – that is what the text on its back tells you to do.","kw":["railway barrier","boom gate","bom"],"img":"Y3-1","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/sakerhetsanordningar-i-korsningar-med-jarnvag-eller-sparvag/bom/","related":["Y1","A35"]},{"id":"Y4","cat":"Y","sv":"Plankorsningsskärm","en":"Level crossing marker board","svText":"Skärmen används för att göra en plankorsning lättare att upptäcka. Skärmen är anpassad till förhållandena på platsen och kan vara liggande.","enText":"Makes a level crossing easier to notice. It is adapted to the place and may be placed lying down.","tip":"","kw":["crossing board"],"img":"Y4","variants":[],"url":"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/vagmarken/sakerhetsanordningar-i-korsningar-med-jarnvag-eller-sparvag/plankorsningsskarm/","related":["A39"]}];
